module.exports = [{"id":"redis-MySQL两千万条Redis只存二十万如何保证是热数据","module":"redis","title":"MySQL两千万条Redis只存二十万如何保证是热数据","level":"core","summary":"题怎么理解","blocks":[{"type":"li","inlines":[{"t":"text","v":"考的是淘汰策略，不是过期策略"}]},{"type":"li","inlines":[{"t":"text","v":"设 maxmemory"}]},{"type":"li","inlines":[{"t":"text","v":"用 allkeys-lfu / volatile-lfu 留热数据"}]},{"type":"p","inlines":[{"t":"text","v":"题怎么理解"}]},{"type":"p","inlines":[{"t":"text","v":"MySQL 两千万，Redis 只能放大约二十万——空间不够，就必须 自动把冷的踢掉、把热的留下。"}]},{"type":"p","inlines":[{"t":"text","v":"这题考的是 内存淘汰策略（"},{"t":"code","v":"maxmemory-policy"},{"t":"text","v":"），别答成过期策略（TTL 到了才删）。过期是时间到了；淘汰是内存满了。"}]},{"type":"p","inlines":[{"t":"text","v":"口述答案"}]},{"type":"p","inlines":[{"t":"text","v":"先设 "},{"t":"code","v":"maxmemory"},{"t":"text","v":"，把 Redis 内存钉死，满了才按策略腾地方。"}]},{"type":"p","inlines":[{"t":"text","v":"策略分两拨看："}]},{"type":"p","inlines":[{"t":"text","v":"不淘汰"}]},{"type":"li","inlines":[{"t":"code","v":"noeviction"},{"t":"text","v":"：默认常见。满了写入直接报错，不会自动变「热数据集合」。"}]},{"type":"p","inlines":[{"t":"text","v":"按范围"}]},{"type":"li","inlines":[{"t":"code","v":"volatile-*"},{"t":"text","v":"：只在「带过期时间」的 key 里淘汰"}]},{"type":"li","inlines":[{"t":"code","v":"allkeys-*"},{"t":"text","v":"：在全部 key 里淘汰"}]},{"type":"p","inlines":[{"t":"text","v":"按规则（和热数据相关的）"}]},{"type":"li","inlines":[{"t":"code","v":"random"},{"t":"text","v":"：随机踢（"},{"t":"code","v":"volatile-random"},{"t":"text","v":" / "},{"t":"code","v":"allkeys-random"},{"t":"text","v":"）"}]},{"type":"li","inlines":[{"t":"code","v":"volatile-ttl"},{"t":"text","v":"：快过期的先踢"}]},{"type":"li","inlines":[{"t":"code","v":"lru"},{"t":"text","v":"：最久没访问的先踢（"},{"t":"code","v":"volatile-lru"},{"t":"text","v":" / "},{"t":"code","v":"allkeys-lru"},{"t":"text","v":"）"}]},{"type":"li","inlines":[{"t":"code","v":"lfu"},{"t":"text","v":"：访问次数少的先踢（"},{"t":"code","v":"volatile-lfu"},{"t":"text","v":" / "},{"t":"code","v":"allkeys-lfu"},{"t":"text","v":"，Redis 4.0 起）"}]},{"type":"p","inlines":[{"t":"text","v":"要保证剩下的是热数据：优先 LFU。它按访问频率，比「最近用没用过」的 LRU 更贴「谁够热」。"}]},{"type":"li","inlines":[{"t":"text","v":"缓存 key 都设了过期 → 可考虑 "},{"t":"code","v":"volatile-lfu"}]},{"type":"li","inlines":[{"t":"text","v":"整库都当缓存、都能丢 → 更常用 "},{"t":"code","v":"allkeys-lfu"}]},{"type":"p","inlines":[{"t":"text","v":"再配合业务：读路径正常写缓存、热点预热；淘汰只是内存顶不住时的自动筛选。"}]},{"type":"p","inlines":[{"t":"text","v":"一句话收束"}]},{"type":"p","inlines":[{"t":"text","v":"空间不够就靠淘汰；想留热数据，开 "},{"t":"code","v":"maxmemory"},{"t":"text","v":"，优先 "},{"t":"code","v":"allkeys-lfu"},{"t":"text","v":"（或带 TTL 时用 "},{"t":"code","v":"volatile-lfu"},{"t":"text","v":"）。"}]}]},{"id":"redis-MySQL两千万条Redis只存二十万如何保证是热数据-和过期策略有什么区别","module":"redis","title":"和过期策略有什么区别","level":"extra","summary":"过期：key 带 TTL，定期 + 惰性删。淘汰：内存到上限，按 policy 选 …","blocks":[{"type":"p","inlines":[{"t":"text","v":"过期：key 带 TTL，定期 + 惰性删。淘汰：内存到上限，按 policy 选 key 删。本题 Redis 容量远小于 MySQL，核心靠淘汰把冷数据挤出去。"}]}],"parentId":"redis-MySQL两千万条Redis只存二十万如何保证是热数据"},{"id":"redis-MySQL两千万条Redis只存二十万如何保证是热数据-为什么更推荐-LFU-而不是-LRU","module":"redis","title":"为什么更推荐 LFU 而不是 LRU","level":"extra","summary":"LRU 看「最近一次」：偶尔扫过一次的冷 key，可能比真正的热 key 看起来「更…","blocks":[{"type":"p","inlines":[{"t":"text","v":"LRU 看「最近一次」：偶尔扫过一次的冷 key，可能比真正的热 key 看起来「更新」。LFU 带访问计数，频繁访问的更不容易被踢，更符合「热数据」直觉。"}]}],"parentId":"redis-MySQL两千万条Redis只存二十万如何保证是热数据"},{"id":"redis-说说红锁及其实现原理","module":"redis","title":"说说红锁及其实现原理","level":"core","summary":"它是什么","blocks":[{"type":"li","inlines":[{"t":"text","v":"多台独立 Redis，多数派加锁"}]},{"type":"li","inlines":[{"t":"text","v":"SET key value NX EX"}]},{"type":"li","inlines":[{"t":"text","v":"耗时 < TTL 才算成功"}]},{"type":"li","inlines":[{"t":"text","v":"失败要对全部节点解锁"}]},{"type":"p","inlines":[{"t":"text","v":"它是什么"}]},{"type":"p","inlines":[{"t":"text","v":"红锁（Redlock）是 Redis 作者提出的一种 分布式锁 算法。单机 Redis 锁：主挂了、主从切换，可能两个人同时以为自己拿到锁。红锁用 多台互相独立的 Redis 主节点 协作，提高容错，不是靠主从复制那一套。"}]},{"type":"p","inlines":[{"t":"text","v":"部署要求（先背这三条）"}]},{"type":"li","inlines":[{"t":"text","v":"至少 N 个独立 Redis 主节点，官方常举 N=5，最好落在不同机器上"}]},{"type":"li","inlines":[{"t":"text","v":"节点之间 不要 做成主从去「凑」红锁；也不要一台机器开多个实例糊弄独立性"}]},{"type":"li","inlines":[{"t":"text","v":"各机器时钟尽量同步，钟差太大会让「有效期」判断变糊"}]},{"type":"p","inlines":[{"t":"text","v":"加锁流程（口述主线）"}]},{"type":"li","inlines":[{"t":"text","v":"记开始时间 "},{"t":"code","v":"start"},{"t":"text","v":"（毫秒）"}]},{"type":"li","inlines":[{"t":"text","v":"依次（或并行）向 N 个节点加锁：同一个 "},{"t":"code","v":"key"},{"t":"text","v":"、同一个随机 "},{"t":"code","v":"value"},{"t":"text","v":"（如 UUID），命令都是"}]},{"type":"p","inlines":[{"t":"code","v":"SET key value NX EX 秒"}]},{"type":"li","inlines":[{"t":"text","v":"NX：没有才设"}]},{"type":"li","inlines":[{"t":"text","v":"EX：过期时间，防死锁"}]},{"type":"li","inlines":[{"t":"text","v":"单节点要短超时（比如几十毫秒）。某个节点挂了或卡住，立刻放弃它，别拖死整次加锁"}]},{"type":"li","inlines":[{"t":"text","v":"算成功要同时满足"}]},{"type":"li","inlines":[{"t":"text","v":"成功节点数 ≥ N/2 + 1（5 台至少 3 台）"}]},{"type":"li","inlines":[{"t":"text","v":"从 start 到现在，总耗时 仍小于锁的 TTL"}]},{"type":"li","inlines":[{"t":"text","v":"成功：可以干业务。注意：节点上 TTL 还是当初设的那么长，但你真正能安心用的时间 ≈ TTL − 加锁耗时，要留余量"}]},{"type":"li","inlines":[{"t":"text","v":"失败：立刻对 所有节点 发解锁（包括你以为没加上的），清脏锁；可短暂随机退避后重试几次，还不行就当加锁失败"}]},{"type":"p","inlines":[{"t":"text","v":"未达多数派的例子：「A 拿了 2 台、B 拿了 2 台、C 拿了 1 台」——谁都没到 3，谁都不能宣布持锁，各自应释放已拿到的。"}]},{"type":"p","inlines":[{"t":"text","v":"解锁怎么做"}]},{"type":"li","inlines":[{"t":"text","v":"向 全部 节点发解锁，用 Lua：只有 "},{"t":"code","v":"value"},{"t":"text","v":" 对得上才 DEL，避免误删别人的锁"}]},{"type":"li","inlines":[{"t":"text","v":"允许部分节点网络失败；尽量清干净，清不掉也靠 TTL 兜底"}]},{"type":"p","inlines":[{"t":"text","v":"注意点和适用场景"}]},{"type":"li","inlines":[{"t":"text","v":"依赖时钟、受网络分区影响，不是强一致 银弹；实现比单机锁复杂"}]},{"type":"li","inlines":[{"t":"text","v":"能容忍短时不一致、要性能和多节点容错：排程、抢资源、发号等可以考虑"}]},{"type":"li","inlines":[{"t":"text","v":"金融级强一致，更常评估 ZooKeeper / etcd 等 CP 方案；生产也可用 Redisson 等封装，但原理要会讲"}]},{"type":"p","inlines":[{"t":"text","v":"一句话收束"}]},{"type":"p","inlines":[{"t":"text","v":"红锁 = 多独立节点 + 同一把 key/随机 value + 多数派成功且耗时小于 TTL；失败全员解锁，解锁校验 value。"}]}]},{"id":"redis-说说红锁及其实现原理-和单机-Redis-锁差在哪","module":"redis","title":"和单机 Redis 锁差在哪","level":"extra","summary":"单机：一个 Redis 上 SET NX EX。主从切换或节点挂了，安全性弱。红锁：…","blocks":[{"type":"p","inlines":[{"t":"text","v":"单机：一个 Redis 上 "},{"t":"code","v":"SET NX EX"},{"t":"text","v":"。主从切换或节点挂了，安全性弱。红锁：多独立主节点多数派，单点挂了还能靠其余节点撑住互斥（在算法假设成立时）。"}]}],"parentId":"redis-说说红锁及其实现原理"},{"id":"redis-说说红锁及其实现原理-为什么必须随机-value","module":"redis","title":"为什么必须随机 value","level":"extra","summary":"解锁时用来证明「锁是我加的」。没有唯一 value，可能把别人续上的锁删掉。","blocks":[{"type":"p","inlines":[{"t":"text","v":"解锁时用来证明「锁是我加的」。没有唯一 value，可能把别人续上的锁删掉。"}]}],"parentId":"redis-说说红锁及其实现原理"},{"id":"redis-说说红锁及其实现原理-为什么加锁失败还要解锁所有节点","module":"redis","title":"为什么加锁失败还要解锁所有节点","level":"extra","summary":"可能有的节点已经 SET 成功，你只是没凑够多数或超时了。不清理会留下脏锁，别人更难…","blocks":[{"type":"p","inlines":[{"t":"text","v":"可能有的节点已经 SET 成功，你只是没凑够多数或超时了。不清理会留下脏锁，别人更难加上。"}]}],"parentId":"redis-说说红锁及其实现原理"},{"id":"redis-说说红锁及其实现原理-为什么加锁要用-SET-key-value-NX-EX-一条命令","module":"redis","title":"为什么加锁要用 SET key value NX EX 一条命令","level":"extra","summary":"SET 完再单独 EXPIRE 不是原子的：进程在两步之间挂了，锁可能永远不过期 →…","blocks":[{"type":"p","inlines":[{"t":"code","v":"SET"},{"t":"text","v":" 完再单独 "},{"t":"code","v":"EXPIRE"},{"t":"text","v":" 不是原子的：进程在两步之间挂了，锁可能永远不过期 → 死锁。"},{"t":"code","v":"SET key value NX EX 秒"},{"t":"text","v":"（或 "},{"t":"code","v":"PX"},{"t":"text","v":"）一次完成「不存在才设 + 带过期」，这是单机 Redis 分布式锁的底线写法。"}]}],"parentId":"redis-说说红锁及其实现原理"},{"id":"redis-说说红锁及其实现原理-解锁为什么必须用-Lua-校验-value","module":"redis","title":"解锁为什么必须用 Lua 校验 value","level":"extra","summary":"正确解锁是「先看 value 是不是我的，再 DEL」。拆成两条命令：线程 A 判断…","blocks":[{"type":"p","inlines":[{"t":"text","v":"正确解锁是「先看 value 是不是我的，再 DEL」。拆成两条命令：线程 A 判断完 value 对上之后，锁刚好过期被 B 抢走，A 再 DEL 就会删掉 B 的锁。用 Lua 把「比对 value + DEL」放进一次脚本执行，中间插不进别的命令。"}]}],"parentId":"redis-说说红锁及其实现原理"},{"id":"redis-Redis主节点挂了会导致超卖吗","module":"redis","title":"Redis主节点挂了会导致超卖吗","level":"core","summary":"题怎么答","blocks":[{"type":"li","inlines":[{"t":"text","v":"会有风险"}]},{"type":"li","inlines":[{"t":"text","v":"根因：主从异步复制"}]},{"type":"li","inlines":[{"t":"text","v":"单机分布式锁可能失效"}]},{"type":"li","inlines":[{"t":"text","v":"对策：红锁 / Lua 原子 / 业务层兜底"}]},{"type":"p","inlines":[{"t":"text","v":"题怎么答"}]},{"type":"p","inlines":[{"t":"text","v":"会有风险，不能说绝对不会。"}]},{"type":"p","inlines":[{"t":"text","v":"Redis 主从默认是 异步同步：客户端写主库成功返回后，从库未必已经收到。主刚好在「已写未同步」时挂掉，从提升成新主，就可能丢最近一次写入——库存、锁 key 都一样。"}]},{"type":"p","inlines":[{"t":"text","v":"为什么会超卖（两条线）"}]},{"type":"p","inlines":[{"t":"text","v":"1. 库存数据不一致"}]},{"type":"p","inlines":[{"t":"text","v":"线程把库存扣减写到主 → 主还没同步到从就挂了 → 新主仍是旧库存 → 另一个请求再扣一次 → 超卖。"}]},{"type":"p","inlines":[{"t":"text","v":"2. 单机分布式锁失效"}]},{"type":"p","inlines":[{"t":"text","v":"线程 1 在主上 "},{"t":"code","v":"SET NX"},{"t":"text","v":" 拿到锁（Redisson 等）→ 锁 key 还没同步到从 → 主挂 → 从变新主且没有这把锁 → 线程 2 又能加到同一把锁 → 两个人同时进临界区，库存再被扣穿。"}]},{"type":"p","inlines":[{"t":"text","v":"所以：不是「集群」三个字保证不超卖，异步复制 + 故障切换 才是坑。"}]},{"type":"p","inlines":[{"t":"text","v":"和红锁的关系"}]},{"type":"p","inlines":[{"t":"text","v":"单节点（或主从当一把锁用）扛不住上面那种切换。红锁用多台 独立主节点、多数派成功才算持锁，某个节点挂了也不容易两个人同时「都以为拿到锁」。超卖场景里，红锁是锁层面的加强，不是唯一解。"}]},{"type":"p","inlines":[{"t":"text","v":"还有哪些解法（一起背）"}]},{"type":"li","inlines":[{"t":"text","v":"原子命令 / Lua：扣库存用 "},{"t":"code","v":"DECR"},{"t":"text","v":" / "},{"t":"code","v":"INCRBY"},{"t":"text","v":" 或 Lua 里「查+扣」一次完成，避免业务上先读后写两段命令中间被插队"}]},{"type":"li","inlines":[{"t":"text","v":"乐观锁：版本号 / CAS，库存变了就重试"}]},{"type":"li","inlines":[{"t":"text","v":"消息队列削峰：下单进队串行或限流处理，降低并发砸库、砸缓存"}]},{"type":"li","inlines":[{"t":"text","v":"业务兜底：DB 唯一约束、库存扣减条件更新（"},{"t":"code","v":"stock > 0"},{"t":"text","v":"）、对账补偿"}]},{"type":"p","inlines":[{"t":"text","v":"一句话收束"}]},{"type":"p","inlines":[{"t":"text","v":"主挂了 + 异步复制 → 可能丢锁、丢扣减 → 可能超卖；单机锁不够就上红锁或多节点共识，库存本身尽量原子操作，并在 DB 层留底线。"}]}]},{"id":"redis-Redis主节点挂了会导致超卖吗-主从同步改成同步复制能根治吗","module":"redis","title":"主从同步改成同步复制能根治吗","level":"extra","summary":"WAIT 等可以降低丢写概率，但延迟、可用性会变差，网络分区时更麻烦，一般不靠它当超…","blocks":[{"type":"p","inlines":[{"t":"code","v":"WAIT"},{"t":"text","v":" 等可以降低丢写概率，但延迟、可用性会变差，网络分区时更麻烦，一般不靠它当超卖银弹。更稳的是：锁用多数派或 ZK/etcd，库存用原子 + DB 约束。"}]}],"parentId":"redis-Redis主节点挂了会导致超卖吗"},{"id":"redis-Redis主节点挂了会导致超卖吗-Redisson-看门狗和超卖有什么关系","module":"redis","title":"Redisson 看门狗和超卖有什么关系","level":"extra","summary":"看门狗是 持锁期间自动续期，防业务没跑完锁先过期。它解决不了「主挂了、锁没同步到从」…","blocks":[{"type":"p","inlines":[{"t":"text","v":"看门狗是 持锁期间自动续期，防业务没跑完锁先过期。它解决不了「主挂了、锁没同步到从」——续期也是续在旧主上。主从切换丢锁，还是要靠红锁或多节点方案。"}]}],"parentId":"redis-Redis主节点挂了会导致超卖吗"},{"id":"redis-Redis主节点挂了会导致超卖吗-面试怎么和红锁那题串起来","module":"redis","title":"面试怎么和红锁那题串起来","level":"extra","summary":"先答：单机锁 + 主从异步会丢锁导致超卖；再答：红锁用独立多节点多数派降低这种风险；…","blocks":[{"type":"p","inlines":[{"t":"text","v":"先答：单机锁 + 主从异步会丢锁导致超卖；再答：红锁用独立多节点多数派降低这种风险；最后补：库存仍建议 Lua/原子 + DB 兜底，锁只是互斥手段之一。"}]}],"parentId":"redis-Redis主节点挂了会导致超卖吗"},{"id":"redis-为什么不能用Redis处理过期订单","module":"redis","title":"为什么不能用Redis处理过期订单","level":"core","summary":"题在问什么","blocks":[{"type":"li","inlines":[{"t":"text","v":"别用 key 过期监听关单"}]},{"type":"li","inlines":[{"t":"text","v":"通知有延迟、不保证送达"}]},{"type":"li","inlines":[{"t":"text","v":"优先专业延迟 MQ；其次 Redisson DelayedQueue + 补偿"}]},{"type":"p","inlines":[{"t":"text","v":"题在问什么"}]},{"type":"p","inlines":[{"t":"text","v":"很多人下单时："},{"t":"code","v":"SET order:xxx 1 EX 1800"},{"t":"text","v":"，再开 Redis 过期监听（keyspace notification），key 一过期就改订单状态。面试要答：这套不能当关单的主方案，不可靠。"}]},{"type":"p","inlines":[{"t":"text","v":"为什么不行（两条硬伤）"}]},{"type":"p","inlines":[{"t":"text","v":"1. 过期有延迟"}]},{"type":"p","inlines":[{"t":"text","v":"通知是在 Redis 真正删掉 key 时才发，不是 TTL 归零那一瞬间。删 key 靠定期抽样 + 惰性删除，忙的时候通知可能晚很多，关单时间飘了，业务受不了。"}]},{"type":"p","inlines":[{"t":"text","v":"2. 「发送即忘」，不保证投递"}]},{"type":"p","inlines":[{"t":"text","v":"过期事件类似发完就不管。监听进程当时挂了、断连、重启，这条通知就没了，不会重试。订单可能一直卡在「待支付」。"}]},{"type":"p","inlines":[{"t":"text","v":"所以：过期监听适合辅助感知，不适合订单生命周期这种必须落地的任务。"}]},{"type":"p","inlines":[{"t":"text","v":"常见替代（对比着背）"}]},{"type":"p","inlines":[{"t":"text","v":"| 方案 | 优点 | 缺点 |"}]},{"type":"p","inlines":[{"t":"text","v":"| --- | --- | --- |"}]},{"type":"p","inlines":[{"t":"text","v":"| Redis 过期监听 | 实现简单 | 延迟 + 易丢，不要用于关单 |"}]},{"type":"p","inlines":[{"t":"text","v":"| RabbitMQ 死信/延迟队列 | 能做延迟 | 往往不保证准时投递，前面消息堵了后面也拖 |"}]},{"type":"p","inlines":[{"t":"text","v":"| 时间轮 | 高效 | 多在内存，进程挂了任务丢 |"}]},{"type":"p","inlines":[{"t":"text","v":"| Redisson DelayedQueue（ZSet） | 仍用 Redis，比裸监听稳 | 依赖 Redis，要配补偿 |"}]},{"type":"p","inlines":[{"t":"text","v":"| RocketMQ / Pulsar 定时消息 | 可靠、适合高并发 | 多一套中间件 |"}]},{"type":"p","inlines":[{"t":"text","v":"推荐怎么答"}]},{"type":"li","inlines":[{"t":"text","v":"首选：专业消息队列的延迟/定时消息（RocketMQ、Pulsar 等）——下单写库 + 发延迟消息，到点消费再改状态（先查库确认仍未支付）。"}]},{"type":"li","inlines":[{"t":"text","v":"没有专业 MQ：可用 Redisson DelayedQueue，但 Redis 挂了仍可能丢，要加 补偿（定时扫库未支付超时单）。"}]},{"type":"li","inlines":[{"t":"text","v":"时间轮：临时方案，必须想清楚持久化和重启恢复。"}]},{"type":"li","inlines":[{"t":"text","v":"明确表态：生产关单 不要 用 Redis key 过期监听。"}]},{"type":"p","inlines":[{"t":"text","v":"一句话收束"}]},{"type":"p","inlines":[{"t":"text","v":"过期监听不准时、不保达；关单用延迟 MQ 或 DelayedQueue + 扫库补偿，别绑在 Redis 删 key 上。"}]}]},{"id":"redis-为什么不能用Redis处理过期订单-那-Redis-过期还能干什么","module":"redis","title":"那 Redis 过期还能干什么","level":"extra","summary":"缓存失效、非关键的统计提示、可丢失的旁路信号可以。钱、库存、订单状态这种必须可追溯、…","blocks":[{"type":"p","inlines":[{"t":"text","v":"缓存失效、非关键的统计提示、可丢失的旁路信号可以。钱、库存、订单状态这种必须可追溯、可补偿的，不要押在过期通知上。"}]}],"parentId":"redis-为什么不能用Redis处理过期订单"},{"id":"redis-为什么不能用Redis处理过期订单-用了延迟-MQ-还要注意什么","module":"redis","title":"用了延迟 MQ 还要注意什么","level":"extra","summary":"消费端要 幂等：先查订单是否已支付/已关，再更新。消息可能重复投递；也可能业务已支付…","blocks":[{"type":"p","inlines":[{"t":"text","v":"消费端要 幂等：先查订单是否已支付/已关，再更新。消息可能重复投递；也可能业务已支付，延迟消息才到，不能误关。"}]}],"parentId":"redis-为什么不能用Redis处理过期订单"},{"id":"redis-Redisson续锁失败怎么办","module":"redis","title":"Redisson续锁失败怎么办","level":"core","summary":"什么是续锁（看门狗）","blocks":[{"type":"li","inlines":[{"t":"text","v":"看门狗默认续期（约 30s，每 10s 续）"}]},{"type":"li","inlines":[{"t":"text","v":"续失败 → 锁可能提前释放 → 并发风险"}]},{"type":"li","inlines":[{"t":"text","v":"应对：合理 leaseTime、幂等补偿、监控、别堵死续期线程"}]},{"type":"p","inlines":[{"t":"text","v":"什么是续锁（看门狗）"}]},{"type":"p","inlines":[{"t":"text","v":"Redisson 加锁成功后，若 没指定 leaseTime，会启用 watchdog（看门狗）："}]},{"type":"li","inlines":[{"t":"text","v":"默认锁过期大约 30 秒"}]},{"type":"li","inlines":[{"t":"text","v":"后台大约每 10 秒 检查：还持有锁就再续到 30 秒"}]},{"type":"p","inlines":[{"t":"text","v":"作用：业务跑得比 30 秒久时，锁不会中途自己过期被人抢走。拿不到锁的线程会重试/等待（类似自旋等），不是看门狗的事。"}]},{"type":"p","inlines":[{"t":"text","v":"续锁为什么会失败"}]},{"type":"li","inlines":[{"t":"text","v":"和 Redis 断连，心跳/续期命令发不出去"}]},{"type":"li","inlines":[{"t":"text","v":"客户端进程挂了、被杀、看门狗线程没了"}]},{"type":"li","inlines":[{"t":"text","v":"网络抖动，续期命令超时失败"}]},{"type":"li","inlines":[{"t":"text","v":"JVM Full GC、线程池打满，续期任务被拖死"}]},{"type":"p","inlines":[{"t":"text","v":"续失败会怎样"}]},{"type":"p","inlines":[{"t":"text","v":"锁 TTL 到了自动释放 → 业务还没跑完，别人又能加上同一把锁 → 互斥破掉，可能重复扣库存、数据不一致。"}]},{"type":"p","inlines":[{"t":"text","v":"（死锁更多是「没 unlock / 逻辑写坏」；续失败本身通常是锁提前没了，不是锁永远占着。）"}]},{"type":"p","inlines":[{"t":"text","v":"怎么应对（口述条理）"}]},{"type":"li","inlines":[{"t":"text","v":"设合理过期时间：关键路径用 "},{"t":"code","v":"tryLock(waitTime, leaseTime, unit)"},{"t":"text","v":"，leaseTime 按业务上限估（如 30～60s），不完全死磕自动续期。"}]},{"type":"li","inlines":[{"t":"text","v":"业务幂等 + 补偿：假设锁可能丢，扣库存等要可重入校验；异常记补偿任务，能回滚或对账。"}]},{"type":"li","inlines":[{"t":"text","v":"解锁写严谨："},{"t":"code","v":"finally"},{"t":"text","v":" 里判断 "},{"t":"code","v":"isHeldByCurrentThread()"},{"t":"text","v":" 再 "},{"t":"code","v":"unlock"},{"t":"text","v":"，别误删别人的锁。"}]},{"type":"li","inlines":[{"t":"text","v":"监控：关注加锁/续期/解锁日志，必要看 key 的 TTL；续期失败要告警。"}]},{"type":"li","inlines":[{"t":"text","v":"Redis 高可用：哨兵/集群，少因单点挂了续不上。"}]},{"type":"li","inlines":[{"t":"text","v":"别拖死续期：减少长时间 STW、保证 Redisson 用的线程池健康。"}]},{"type":"p","inlines":[{"t":"text","v":"示例骨架（背结构即可）："}]},{"type":"code","text":"RLock lock = redissonClient.getLock(\"inventoryLock\");\nboolean locked = false;\ntry {\n    locked = lock.tryLock(3, 30, TimeUnit.SECONDS);\n    if (locked) {\n        processInventory(); // 业务尽量幂等\n    }\n} catch (Exception e) {\n    // 记补偿 / 告警\n} finally {\n    if (locked && lock.isHeldByCurrentThread()) {\n        lock.unlock();\n    }\n}"},{"type":"p","inlines":[{"t":"text","v":"一句话收束"}]},{"type":"p","inlines":[{"t":"text","v":"看门狗保长任务不断锁；续失败等于锁可能提前丢，靠合理超时、幂等补偿和监控兜底，不能假设锁永远有效。"}]}]},{"id":"redis-Redisson续锁失败怎么办-指定了-leaseTime-还会看门狗吗","module":"redis","title":"指定了 leaseTime 还会看门狗吗","level":"extra","summary":"一般 不会。tryLock(wait, lease, unit) 指定租约后，到点就…","blocks":[{"type":"p","inlines":[{"t":"text","v":"一般 不会。"},{"t":"code","v":"tryLock(wait, lease, unit)"},{"t":"text","v":" 指定租约后，到点就过期，靠你自己保证业务在租约内跑完，或自行续期。没传 lease、用默认加锁时，才走看门狗。"}]}],"parentId":"redis-Redisson续锁失败怎么办"},{"id":"redis-Redisson续锁失败怎么办-续锁失败和主从切换丢锁是一回事吗","module":"redis","title":"续锁失败和主从切换丢锁是一回事吗","level":"extra","summary":"不是。续失败：客户端续不上，锁在原节点过期。主从切换丢锁：锁写在主上还没同步到从，主…","blocks":[{"type":"p","inlines":[{"t":"text","v":"不是。续失败：客户端续不上，锁在原节点过期。主从切换丢锁：锁写在主上还没同步到从，主挂了新主没有锁。都可能导致「两人同时持锁感」，但根因不同；后者要想到红锁/多节点。"}]}],"parentId":"redis-Redisson续锁失败怎么办"},{"id":"redis-Redisson续锁失败怎么办-Redisson-底层为什么用-Lua","module":"redis","title":"Redisson 底层为什么用 Lua","level":"extra","summary":"加锁 / 解锁 / 可重入都是多步：判断 key、写 Hash（owner → 重入…","blocks":[{"type":"p","inlines":[{"t":"text","v":"加锁 / 解锁 / 可重入都是多步：判断 key、写 Hash（owner → 重入次数）、设过期。Lua 在 Redis 里一次跑完，避免「判断完、还没写完」被并发打断。和「解锁必须校验 identity」是同一套原子性要求。"}]}],"parentId":"redis-Redisson续锁失败怎么办"},{"id":"redis-Redisson续锁失败怎么办-拿不到锁的线程怎么等","module":"redis","title":"拿不到锁的线程怎么等","level":"extra","summary":"常见实现：拿不到就 阻塞等待（可用信号量一类结构占住），持锁方 unlock 时通过…","blocks":[{"type":"p","inlines":[{"t":"text","v":"常见实现：拿不到就 阻塞等待（可用信号量一类结构占住），持锁方 "},{"t":"code","v":"unlock"},{"t":"text","v":" 时通过 Redis 发布订阅 叫醒等待者再去抢，而不是纯盲自旋狂打 Redis。口述记：Lua 抢锁 + 看门狗续命 + Pub/Sub 唤醒。"}]}],"parentId":"redis-Redisson续锁失败怎么办"},{"id":"redis-如何用Redis统计用户访问量UV","module":"redis","title":"如何用Redis统计用户访问量UV","level":"core","summary":"场景：页面 UV（独立访客）。登录用 userId；未登录可用前端生成的唯一标识。","blocks":[{"type":"li","inlines":[{"t":"text","v":"Hash：准，费内存"}]},{"type":"li","inlines":[{"t":"text","v":"Bitmap：省内存，怕 ID 稀疏"}]},{"type":"li","inlines":[{"t":"text","v":"HyperLogLog：极省，允许误差"}]},{"type":"p","inlines":[{"t":"text","v":"场景：页面 UV（独立访客）。登录用 userId；未登录可用前端生成的唯一标识。"}]},{"type":"p","inlines":[{"t":"text","v":"方案一：Hash"}]},{"type":"p","inlines":[{"t":"text","v":"思路：一个 key 表示「某页某天」，field 是用户，value 随意占位。"}]},{"type":"code","text":"HSET {uri}:{date} {userId} 1\nHLEN {uri}:{date}   → UV"},{"type":"p","inlines":[{"t":"text","v":"例："},{"t":"code","v":"HSET index.html0224 baili 1"},{"t":"text","v":"，再 "},{"t":"code","v":"HLEN"},{"t":"text","v":" 得去重人数。"}]},{"type":"li","inlines":[{"t":"text","v":"优点：实现简单，结果准，能按用户查有没有来过（看 field）"}]},{"type":"li","inlines":[{"t":"text","v":"缺点：人一多内存炸；大站海量 UV 扛不住"}]},{"type":"p","inlines":[{"t":"text","v":"适合：访问量不大、要精确、还要知道「谁来过」。"}]},{"type":"p","inlines":[{"t":"text","v":"方案二：Bitmap"}]},{"type":"p","inlines":[{"t":"text","v":"把 String 当 bit 数组：偏移量 ≈ 用户 ID，来过就 "},{"t":"code","v":"SETBIT"},{"t":"text","v":" 成 1。"}]},{"type":"code","text":"SETBIT {uri}:{date} {userId} 1\nGETBIT {uri}:{date} {userId}   → 是否来过\nBITCOUNT {uri}:{date}          → UV"},{"type":"p","inlines":[{"t":"text","v":"1 个 bit 管 1 个用户；约 1 亿用户大约十几 MB 量级（远小于每人存一个 ID）。未登录 ID 可先哈希成数字偏移。"}]},{"type":"li","inlines":[{"t":"text","v":"优点：内存省，查「某人来没来」方便"}]},{"type":"li","inlines":[{"t":"text","v":"缺点：ID 很稀疏（1 和 10000000）中间空位也占空间；未登录映射要额外设计"}]},{"type":"p","inlines":[{"t":"text","v":"适合：userId 较连续、要省内存又要精确一点、还要查单用户。"}]},{"type":"p","inlines":[{"t":"text","v":"方案三：HyperLogLog"}]},{"type":"p","inlines":[{"t":"text","v":"基数估算，不存具体用户，只存估算用的状态。"}]},{"type":"code","text":"PFADD {uri}:{date} user1 user2 ...\nPFCOUNT {uri}:{date}   → 估算 UV"},{"type":"p","inlines":[{"t":"text","v":"单 key 大约 12KB，误差大约 0.81%。亿级 UV 差几十万通常可接受。"}]},{"type":"li","inlines":[{"t":"text","v":"优点：内存极小，适合超大流量粗统计"}]},{"type":"li","inlines":[{"t":"text","v":"缺点：不准到人；查不了「某用户在不在」"}]},{"type":"p","inlines":[{"t":"text","v":"适合：大盘 UV、趋势，不要精确名单。"}]},{"type":"p","inlines":[{"t":"text","v":"怎么选（口述）"}]},{"type":"p","inlines":[{"t":"text","v":"要精确 + 流量小 → Hash。"}]},{"type":"p","inlines":[{"t":"text","v":"要精确 + 省内存 + ID 友好 → Bitmap。"}]},{"type":"p","inlines":[{"t":"text","v":"只要大概数字、流量巨大 → HyperLogLog。"}]},{"type":"p","inlines":[{"t":"text","v":"面试先说三种，再按「准不准 / 省不省 / 能不能查人」对比。"}]},{"type":"p","inlines":[{"t":"text","v":"一句话收束"}]},{"type":"p","inlines":[{"t":"text","v":"UV 三板斧：Hash 准但胖，Bitmap 省但怕稀疏，HyperLogLog 最瘦但有误差。"}]}]},{"id":"redis-如何用Redis统计用户访问量UV-PV-和-UV-有什么区别","module":"redis","title":"PV 和 UV 有什么区别","level":"extra","summary":"PV 是点击次数，同一人刷多次算多次，可用 INCR。UV 是去重人数，同一人一天多…","blocks":[{"type":"p","inlines":[{"t":"text","v":"PV 是点击次数，同一人刷多次算多次，可用 INCR。UV 是去重人数，同一人一天多次只算一次，才用上面三种。"}]}],"parentId":"redis-如何用Redis统计用户访问量UV"},{"id":"redis-如何用Redis统计用户访问量UV-HyperLogLog-能删某个用户再重算吗","module":"redis","title":"HyperLogLog 能删某个用户再重算吗","level":"extra","summary":"不能按用户删。它不保存原始集合，只维护估算结构。要精确集合操作用 Set/Hash/…","blocks":[{"type":"p","inlines":[{"t":"text","v":"不能按用户删。它不保存原始集合，只维护估算结构。要精确集合操作用 Set/Hash/Bitmap。"}]}],"parentId":"redis-如何用Redis统计用户访问量UV"},{"id":"redis-如何进行Redis性能调优","module":"redis","title":"如何进行Redis性能调优","level":"core","summary":"面试别一上来改参数。路径是：先定位延迟在哪，再证明 Redis 真变慢了，再对号入座…","blocks":[{"type":"li","inlines":[{"t":"text","v":"先确认是不是 Redis 慢"}]},{"type":"li","inlines":[{"t":"text","v":"对照本机基准延迟"}]},{"type":"li","inlines":[{"t":"text","v":"再按：命令 / bigkey / 过期 / 淘汰 / 持久化 / 系统 查"}]},{"type":"p","inlines":[{"t":"text","v":"面试别一上来改参数。路径是：先定位延迟在哪，再证明 Redis 真变慢了，再对号入座优化。"}]},{"type":"p","inlines":[{"t":"text","v":"第一步：确认慢在 Redis"}]},{"type":"p","inlines":[{"t":"text","v":"业务 API 变慢，不一定是 Redis。链路追踪看 Redis、MySQL、下游各自耗时。"}]},{"type":"p","inlines":[{"t":"text","v":"确认是「到 Redis 这条边」变慢后，还要拆两段："}]},{"type":"li","inlines":[{"t":"text","v":"业务机到 Redis 的 网络（丢包、跨机房）——同机其他服务也慢，多半是网"}]},{"type":"li","inlines":[{"t":"text","v":"Redis 进程自己 处理变慢 —— 下面才是调优重点"}]},{"type":"p","inlines":[{"t":"text","v":"第二步：对照基准性能"}]},{"type":"p","inlines":[{"t":"text","v":"别拿别人的「2ms 就算慢」套自己机器。基准 = 这台生产机上空闲时，实例正常的平均/最大延迟。"}]},{"type":"p","inlines":[{"t":"text","v":"建议在 Redis 本机 测，排除网络："}]},{"type":"code","text":"redis-cli --intrinsic-latency 60\nredis-cli --latency-history -i 1"},{"type":"p","inlines":[{"t":"text","v":"同规格机器上，正常实例做一次对照。延迟到正常基准 约 2 倍以上，可以认为这个实例确实变慢了。"}]},{"type":"p","inlines":[{"t":"text","v":"第三步：从易到难对因"}]},{"type":"p","inlines":[{"t":"text","v":"1. 复杂命令堵主线程"}]},{"type":"p","inlines":[{"t":"text","v":"先开慢日志："}]},{"type":"code","text":"CONFIG SET slowlog-log-slower-than 5000\nCONFIG SET slowlog-max-len 500\nSLOWLOG GET"},{"type":"p","inlines":[{"t":"text","v":"单线程：前面一条 "},{"t":"code","v":"KEYS"},{"t":"text","v":" / "},{"t":"code","v":"SORT"},{"t":"text","v":" / 大集合 "},{"t":"code","v":"SUNION"},{"t":"text","v":" 卡住，后面 "},{"t":"code","v":"GET"},{"t":"text","v":" 全排队。"}]},{"type":"p","inlines":[{"t":"text","v":"优化：禁止线上 "},{"t":"code","v":"KEYS"},{"t":"text","v":"；聚合放到业务侧；"},{"t":"code","v":"LRANGE"},{"t":"text","v":" 等 O(N) 把 N 压小（常说几百以内）。"}]},{"type":"p","inlines":[{"t":"text","v":"2. bigkey"}]},{"type":"p","inlines":[{"t":"text","v":"慢日志里是 "},{"t":"code","v":"GET"},{"t":"text","v":"/"},{"t":"code","v":"DEL"},{"t":"text","v":" 也很慢 → 多半 value 太大。分配、释放、网络回包都贵。扫一眼（线上加 "},{"t":"code","v":"-i"},{"t":"text","v":" 间隔，别打满）："}]},{"type":"code","text":"redis-cli --bigkeys -i 0.1"},{"type":"p","inlines":[{"t":"text","v":"优化：拆 key，别塞大对象；删大 key 用 "},{"t":"code","v":"UNLINK"},{"t":"text","v":"（4.0+），或开 lazy-free，把释放丢给后台。集群迁移、过期、淘汰都会被 bigkey 拖累。"}]},{"type":"p","inlines":[{"t":"text","v":"3. 集中过期"}]},{"type":"p","inlines":[{"t":"text","v":"表现为周期性一波卡顿。主动过期在 主线程 抽样删，过期比例高会循环删，命令要等它。慢日志可能看不到「删过期」这条。"}]},{"type":"p","inlines":[{"t":"text","v":"优化：TTL 加随机抖动；4.0+ lazy-free；盯 "},{"t":"code","v":"INFO"},{"t":"text","v":" 里 "},{"t":"code","v":"expired_keys"},{"t":"text","v":" 是否突增。"}]},{"type":"p","inlines":[{"t":"text","v":"4. 内存顶满在淘汰"}]},{"type":"p","inlines":[{"t":"text","v":"到了 "},{"t":"code","v":"maxmemory"},{"t":"text","v":"，每次写入前先踢 key，写得越猛越堵。淘汰前也占主线程。"}]},{"type":"p","inlines":[{"t":"text","v":"优化：别存 bigkey；实例拆分；必要时 random 比 LRU 踢得快（看业务）；4.0+ "},{"t":"code","v":"lazyfree-lazy-eviction"},{"t":"text","v":"。"}]},{"type":"p","inlines":[{"t":"text","v":"5. fork / 持久化"}]},{"type":"p","inlines":[{"t":"text","v":"BGSAVE、AOF rewrite 要 "},{"t":"code","v":"fork"},{"t":"text","v":"，实例越大拷页越久，fork 期间可能短暂服务不了。看 "},{"t":"code","v":"INFO"},{"t":"text","v":" 的 "},{"t":"code","v":"latest_fork_usec"},{"t":"text","v":"。"}]},{"type":"p","inlines":[{"t":"text","v":"优化：实例内存别盲目上很大；纯缓存可少做 RDB/AOF；避开高峰；降低全量同步。"}]},{"type":"p","inlines":[{"t":"text","v":"fork 之后写时复制：主进程改内存要拷页。开了 透明大页，一次拷 2MB，延迟更明显。Redis 机器建议关 transparent hugepage。"}]},{"type":"p","inlines":[{"t":"text","v":"AOF："},{"t":"code","v":"always"},{"t":"text","v":" 最稳最慢；"},{"t":"code","v":"everysec"},{"t":"text","v":" 常用但仍可能被刷盘堵住 "},{"t":"code","v":"write"},{"t":"text","v":"。rewrite 期间可 "},{"t":"code","v":"no-appendfsync-on-rewrite yes"},{"t":"text","v":"，磁盘用 SSD、别和别的重 IO 抢。"}]},{"type":"p","inlines":[{"t":"text","v":"6. 系统层"}]},{"type":"li","inlines":[{"t":"text","v":"Swap：延迟到百毫秒～秒级，先查进程有没有 Swap。Redis 要够内存，用了 Swap 等于废了"}]},{"type":"li","inlines":[{"t":"text","v":"碎片："},{"t":"code","v":"mem_fragmentation_ratio"},{"t":"text","v":" 过高（常看 >1.5）。4.0+ 可 "},{"t":"code","v":"activedefrag"},{"t":"text","v":"，但整理也占主线程，要压测"}]},{"type":"li","inlines":[{"t":"text","v":"绑核：乱绑一个逻辑核，fork 子进程和主线程抢 CPU。非极致场景可不绑；6.0+ 才有更细的 "},{"t":"code","v":"server_cpulist"},{"t":"text","v":" 等"}]},{"type":"li","inlines":[{"t":"text","v":"网卡打满、短连接：长连接；机器尽量专用 Redis"}]},{"type":"p","inlines":[{"t":"text","v":"一句话收束"}]},{"type":"p","inlines":[{"t":"text","v":"先追踪、再本机基准、再慢日志；命令和 bigkey 最常见，然后过期/淘汰/fork/AOF/Swap。"}]}]},{"id":"redis-如何进行Redis性能调优-slowlog-没有记录但客户端变慢是怎么回事","module":"redis","title":"slowlog 没有记录但客户端变慢是怎么回事","level":"extra","summary":"过期清理、淘汰、fork 发生在「真正执行命令之前」或主线程被系统调用堵住，慢日志只…","blocks":[{"type":"p","inlines":[{"t":"text","v":"过期清理、淘汰、fork 发生在「真正执行命令之前」或主线程被系统调用堵住，慢日志只记命令执行本身。要结合 "},{"t":"code","v":"INFO"},{"t":"text","v":"、"},{"t":"code","v":"expired_keys"},{"t":"text","v":"、"},{"t":"code","v":"latest_fork_usec"},{"t":"text","v":"、磁盘 IO、是否 Swap。"}]}],"parentId":"redis-如何进行Redis性能调优"},{"id":"redis-如何进行Redis性能调优-线上能不能直接---bigkeys","module":"redis","title":"线上能不能直接 --bigkeys","level":"extra","summary":"能，但内部是 SCAN，会占一点 CPU。务必加扫描间隔 -i，高峰慎用，或在从库扫…","blocks":[{"type":"p","inlines":[{"t":"text","v":"能，但内部是 SCAN，会占一点 CPU。务必加扫描间隔 "},{"t":"code","v":"-i"},{"t":"text","v":"，高峰慎用，或在从库扫。"}]}],"parentId":"redis-如何进行Redis性能调优"},{"id":"redis-Redis中key过期了一定会立即删除吗","module":"redis","title":"Redis中key过期了一定会立即删除吗","level":"core","summary":"直接答","blocks":[{"type":"li","inlines":[{"t":"text","v":"不会立即删"}]},{"type":"li","inlines":[{"t":"text","v":"惰性删除 + 定期删除"}]},{"type":"li","inlines":[{"t":"text","v":"冷过期 key 可能占内存，靠淘汰兜底"}]},{"type":"p","inlines":[{"t":"text","v":"直接答"}]},{"type":"p","inlines":[{"t":"text","v":"不会。 Redis 不是 TTL 一到就立刻把 key 从内存抹掉，而是 惰性删除 + 定期删除 配合。细节和核心题「说说 Redis 的过期策略」是一套知识，这题更偏 判断题 + 后果。"}]},{"type":"p","inlines":[{"t":"text","v":"两种机制（背结论）"}]},{"type":"p","inlines":[{"t":"text","v":"惰性删除"}]},{"type":"p","inlines":[{"t":"text","v":"你去访问这个 key 时，发现已经过期，当场删掉再返回不存在。没人访问，惰性就碰不到它。"}]},{"type":"p","inlines":[{"t":"text","v":"定期删除"}]},{"type":"p","inlines":[{"t":"text","v":"后台定时（默认大致和 "},{"t":"code","v":"hz=10"},{"t":"text","v":" 相关，约每秒多轮，常说「约 100ms」一轮）从带过期时间的 key 里 随机抽一批 检查，过期的删掉。不是全表扫描，所以总会有漏网。"},{"t":"code","v":"hz"},{"t":"text","v":" 调大删得勤，也更吃 CPU。"}]},{"type":"p","inlines":[{"t":"text","v":"影响"}]},{"type":"p","inlines":[{"t":"text","v":"过期 key 可能还在内存里待一会儿（甚至更久，如果又冷又没被抽到）。"}]},{"type":"p","inlines":[{"t":"text","v":"惰性几乎不占额外周期；定期开销可控，故意做成轻量，避免拖垮主业务。"}]},{"type":"p","inlines":[{"t":"text","v":"极端情况：要强时效、或内存特别紧，别只指望「过期=立刻没」——业务侧可主动 DEL，并配好 "},{"t":"code","v":"maxmemory"},{"t":"text","v":" 淘汰，把长期躺着的过期 key 清掉。"}]},{"type":"p","inlines":[{"t":"text","v":"一句话收束"}]},{"type":"p","inlines":[{"t":"text","v":"过期 ≠ 立刻删除；访问时删 + 定时抽样删；剩下的靠内存淘汰。"}]}]},{"id":"redis-Redis中key过期了一定会立即删除吗-和「说说过期策略」是不是重复","module":"redis","title":"和「说说过期策略」是不是重复","level":"extra","summary":"问法不同、知识点相同。这题要 先否定立刻删除，再点出两套机制和内存后果。系统讲定期/…","blocks":[{"type":"p","inlines":[{"t":"text","v":"问法不同、知识点相同。这题要 先否定立刻删除，再点出两套机制和内存后果。系统讲定期/惰性/淘汰，用核心题 "},{"t":"code","v":"14.说说Redis的过期策略"},{"t":"text","v":"。"}]}],"parentId":"redis-Redis中key过期了一定会立即删除吗"},{"id":"redis-Redis中key过期了一定会立即删除吗-为什么不用定时器到点就删","module":"redis","title":"为什么不用定时器到点就删","level":"extra","summary":"每个带 TTL 的 key 挂一个精确定时器，过期 key 一多，定时器管理和唤醒成…","blocks":[{"type":"p","inlines":[{"t":"text","v":"每个带 TTL 的 key 挂一个精确定时器，过期 key 一多，定时器管理和唤醒成本很高。抽样 + 惰性是用一点延迟换稳定延迟和 CPU。"}]}],"parentId":"redis-Redis中key过期了一定会立即删除吗"},{"id":"redis-Redis如何高效安全地遍历所有key","module":"redis","title":"Redis如何高效安全地遍历所有key","level":"core","summary":"直接答","blocks":[{"type":"li","inlines":[{"t":"text","v":"生产禁用 KEYS"}]},{"type":"li","inlines":[{"t":"text","v":"用 SCAN 游标分批"}]},{"type":"li","inlines":[{"t":"text","v":"非阻塞、增量式"}]},{"type":"p","inlines":[{"t":"text","v":"直接答"}]},{"type":"p","inlines":[{"t":"text","v":"要遍历全部 key，用 "},{"t":"code","v":"SCAN"},{"t":"text","v":"，不要用 "},{"t":"code","v":"KEYS *"},{"t":"text","v":"。"}]},{"type":"p","inlines":[{"t":"code","v":"KEYS"},{"t":"text","v":" 一次把匹配结果全捞出来，key 多时主线程长时间卡住，内存也会顶一波，线上会雪崩。"},{"t":"code","v":"SCAN"},{"t":"text","v":" 按 游标 一小批一小批扫，中间还能干别的命令。"}]},{"type":"p","inlines":[{"t":"text","v":"SCAN 两个特点"}]},{"type":"p","inlines":[{"t":"text","v":"非阻塞"}]},{"type":"p","inlines":[{"t":"text","v":"每轮只处理一部分，不会像 "},{"t":"code","v":"KEYS"},{"t":"text","v":" 那样长时间占死主线程。"}]},{"type":"p","inlines":[{"t":"text","v":"增量式"}]},{"type":"p","inlines":[{"t":"text","v":"第一次游标从 "},{"t":"code","v":"0"},{"t":"text","v":" 开始，返回「下一游标 + 本批 key」；下次带上新游标继续，直到游标再次回到 "},{"t":"code","v":"0"},{"t":"text","v":" 表示这一轮扫完。"}]},{"type":"p","inlines":[{"t":"text","v":"常用参数："},{"t":"code","v":"MATCH"},{"t":"text","v":" 过滤模式，"},{"t":"code","v":"COUNT"},{"t":"text","v":" 提示每批大概多少（不是硬上限，Redis 可多可少）。"}]},{"type":"p","inlines":[{"t":"text","v":"集合内部遍历用同族命令："},{"t":"code","v":"HSCAN"},{"t":"text","v":" / "},{"t":"code","v":"SSCAN"},{"t":"text","v":" / "},{"t":"code","v":"ZSCAN"},{"t":"text","v":"。"}]},{"type":"p","inlines":[{"t":"text","v":"Java 思路（Jedis）"}]},{"type":"code","text":"String cursor = ScanParams.SCAN_POINTER_START;\nScanParams params = new ScanParams().match(\"*\").count(100);\ndo {\n    ScanResult<String> result = jedis.scan(cursor, params);\n    for (String key : result.getResult()) {\n        // 处理 key\n    }\n    cursor = result.getCursor();\n} while (!cursor.equals(ScanParams.SCAN_POINTER_START));"},{"type":"p","inlines":[{"t":"code","v":"count"},{"t":"text","v":" 按机器负载调：太小扫得慢，太大单次仍偏沉。"}]},{"type":"p","inlines":[{"t":"text","v":"注意点"}]},{"type":"li","inlines":[{"t":"text","v":"扫描过程中 key 可能增删，不保证像快照那样不重不漏；运维统计、清理可接受，强一致全量别指望一遍 SCAN"}]},{"type":"li","inlines":[{"t":"text","v":"高峰对主库狂扫仍占 CPU，可加间隔，或打从库"}]},{"type":"li","inlines":[{"t":"text","v":"Cluster 要按节点分别 SCAN"}]},{"type":"p","inlines":[{"t":"text","v":"一句话收束"}]},{"type":"p","inlines":[{"t":"text","v":"线上遍历用 SCAN 游标分批；KEYS 只适合本地调试。"}]}]},{"id":"redis-Redis如何高效安全地遍历所有key-COUNT-是不是每次一定返回那么多","module":"redis","title":"COUNT 是不是每次一定返回那么多","level":"extra","summary":"不是，只是建议。字典扩容、填充率变化时，单次返回数量会浮动。","blocks":[{"type":"p","inlines":[{"t":"text","v":"不是，只是建议。字典扩容、填充率变化时，单次返回数量会浮动。"}]}],"parentId":"redis-Redis如何高效安全地遍历所有key"},{"id":"redis-Redis如何高效安全地遍历所有key-和---bigkeys-什么关系","module":"redis","title":"和 --bigkeys 什么关系","level":"extra","summary":"--bigkeys 内部就是 SCAN。所以「安全遍历」和「查大 Key」是同一套路…","blocks":[{"type":"p","inlines":[{"t":"code","v":"--bigkeys"},{"t":"text","v":" 内部就是 SCAN。所以「安全遍历」和「查大 Key」是同一套路：分批、别 KEYS。"}]}],"parentId":"redis-Redis如何高效安全地遍历所有key"},{"id":"redis-一个Redis实例最多能存放多少key","module":"redis","title":"一个Redis实例最多能存放多少key","level":"core","summary":"直接答","blocks":[{"type":"li","inlines":[{"t":"text","v":"理论约 2^32 - 1（约 42 亿）"}]},{"type":"li","inlines":[{"t":"text","v":"受哈希表索引位宽限制"}]},{"type":"li","inlines":[{"t":"text","v":"实战远到不了：内存和性能先顶满"}]},{"type":"p","inlines":[{"t":"text","v":"直接答"}]},{"type":"p","inlines":[{"t":"text","v":"理论上限大约是 2³² − 1，也就是 约 42 亿 个 key。和字典（哈希表）用 32 位 量级的索引有关，不是业务随便设的配置项。"}]},{"type":"p","inlines":[{"t":"text","v":"实际能塞多少，还受哈希函数、负载因子、以及 机器内存 约束。面试先报理论数，马上补一句：生产往往被内存和延迟卡住，到不了理论天花板。"}]},{"type":"p","inlines":[{"t":"text","v":"实战怎么看"}]},{"type":"p","inlines":[{"t":"text","v":"key 一多："}]},{"type":"li","inlines":[{"t":"text","v":"内存线性涨（每个 key 还有元数据开销）"}]},{"type":"li","inlines":[{"t":"text","v":"扩容、rehash、过期抽样、"},{"t":"code","v":"SCAN"},{"t":"text","v":"、RDB/AOF 都会更沉"}]},{"type":"li","inlines":[{"t":"text","v":"延迟和 CPU 先变差，实例还没到「42 亿」就不可用了"}]},{"type":"p","inlines":[{"t":"text","v":"所以设计容量按 业务量 + 单 key 平均大小 + 预留 估，不要按 42 亿去堆单机。"}]},{"type":"p","inlines":[{"t":"text","v":"不够怎么办"}]},{"type":"p","inlines":[{"t":"text","v":"单实例扛不住："}]},{"type":"li","inlines":[{"t":"text","v":"Redis Cluster 分片到多节点"}]},{"type":"li","inlines":[{"t":"text","v":"或业务侧 分库分实例"}]},{"type":"p","inlines":[{"t":"text","v":"把压力拆开，而不是死磕一台涨内存。"}]},{"type":"p","inlines":[{"t":"text","v":"一句话收束"}]},{"type":"p","inlines":[{"t":"text","v":"理论约 42 亿；真限制是内存和性能，多了就 Cluster / 分片。"}]}]},{"id":"redis-一个Redis实例最多能存放多少key-这个上限是官方保证的硬配额吗","module":"redis","title":"这个上限是官方保证的硬配额吗","level":"extra","summary":"更准确说是实现层面的量级上限。不同版本、编码细节可能有差异，面试答「约 2³²−1，…","blocks":[{"type":"p","inlines":[{"t":"text","v":"更准确说是实现层面的量级上限。不同版本、编码细节可能有差异，面试答「约 2³²−1，约 42 亿」即可，重点放在「理论 vs 实战」。"}]}],"parentId":"redis-一个Redis实例最多能存放多少key"},{"id":"redis-一个Redis实例最多能存放多少key-和-maxmemory-什么关系","module":"redis","title":"和 maxmemory 什么关系","level":"extra","summary":"maxmemory 限制的是 内存字节数，不是 key 个数。key 很少但都是大 …","blocks":[{"type":"p","inlines":[{"t":"code","v":"maxmemory"},{"t":"text","v":" 限制的是 内存字节数，不是 key 个数。key 很少但都是大 value，也会先触顶淘汰或报错。"}]}],"parentId":"redis-一个Redis实例最多能存放多少key"},{"id":"redis-Redis抖动是什么，如何解决","module":"redis","title":"Redis抖动是什么，如何解决","level":"core","summary":"抖动是什么","blocks":[{"type":"li","inlines":[{"t":"text","v":"延迟偶发尖刺，不是一直慢"}]},{"type":"li","inlines":[{"t":"text","v":"先 INFO / 慢日志 / 大 Key"}]},{"type":"li","inlines":[{"t":"text","v":"再对：内存、网络、持久化、重命令"}]},{"type":"p","inlines":[{"t":"text","v":"抖动是什么"}]},{"type":"p","inlines":[{"t":"text","v":"业务感觉 Redis 一会儿正常、一会儿突然卡一下：P99/P999 延迟飙高，过一会儿又回来。和「整体一直慢」不同，更像 间歇性尖刺。"}]},{"type":"p","inlines":[{"t":"text","v":"单线程模型下，主线程被某一拍堵住（大 Key、重命令、fork、刷盘、淘汰），排队的请求一起抖。"}]},{"type":"p","inlines":[{"t":"text","v":"和拓展题「如何进行 Redis 性能调优」是一套排查思路；这题先定义抖动，再按「监控 → 根因 → 治理」口述。"}]},{"type":"p","inlines":[{"t":"text","v":"怎么诊断（三板斧）"}]},{"type":"p","inlines":[{"t":"text","v":"1. 看运行指标（INFO）"}]},{"type":"p","inlines":[{"t":"text","v":"盯 "},{"t":"code","v":"connected_clients"},{"t":"text","v":"、"},{"t":"code","v":"used_memory"},{"t":"text","v":"、"},{"t":"code","v":"used_cpu_sys"},{"t":"text","v":" / "},{"t":"code","v":"used_cpu_user"},{"t":"text","v":"，以及是否在 Swap、是否频繁淘汰。连接暴涨、内存顶满、CPU 打满，都容易抖。"}]},{"type":"p","inlines":[{"t":"text","v":"2. 看慢日志"}]},{"type":"p","inlines":[{"t":"code","v":"SLOWLOG GET"},{"t":"text","v":"：哪条命令、耗时多少。复杂命令、大返回值常是尖刺来源。"}]},{"type":"p","inlines":[{"t":"text","v":"3. 查大 Key"}]},{"type":"p","inlines":[{"t":"code","v":"SCAN"},{"t":"text","v":" / "},{"t":"code","v":"--bigkeys"},{"t":"text","v":"（尽量从库）。大 Key 的读写、删除会突然堵主线程。"}]},{"type":"p","inlines":[{"t":"text","v":"定期拉这些指标做巡检，比出事后才查稳。"}]},{"type":"p","inlines":[{"t":"text","v":"常见根因"}]},{"type":"li","inlines":[{"t":"text","v":"内存压力：用量过高、key 过多、淘汰频繁；客户端侧也可能因超时重试把连接打爆（别把 Java GC 说成 Redis GC）"}]},{"type":"li","inlines":[{"t":"text","v":"网络：跨机房、带宽打满、丢包，表现为延迟尖刺"}]},{"type":"li","inlines":[{"t":"text","v":"持久化：RDB/AOF 频繁、"},{"t":"code","v":"fork"},{"t":"text","v":"、刷盘堵住"}]},{"type":"li","inlines":[{"t":"text","v":"命令："},{"t":"code","v":"KEYS"},{"t":"text","v":"、大范围 "},{"t":"code","v":"HGETALL"},{"t":"text","v":"/"},{"t":"code","v":"SMEMBERS"},{"t":"text","v":"、过大 Pipeline/聚合"}]},{"type":"p","inlines":[{"t":"text","v":"怎么解决（对着因下药）"}]},{"type":"p","inlines":[{"t":"text","v":"内存"}]},{"type":"p","inlines":[{"t":"text","v":"设合理 "},{"t":"code","v":"maxmemory"},{"t":"text","v":" + 淘汰策略；压缩/拆大 Key；过期加随机，避免集中过期。"}]},{"type":"p","inlines":[{"t":"text","v":"命令"}]},{"type":"p","inlines":[{"t":"text","v":"禁线上 "},{"t":"code","v":"KEYS"},{"t":"text","v":"；O(N) 拆小；批量用 Pipeline，但单批别过大；结构按访问模式设计。"}]},{"type":"p","inlines":[{"t":"text","v":"持久化"}]},{"type":"p","inlines":[{"t":"text","v":"降频率或错峰；纯缓存可弱化持久化；AOF 用 "},{"t":"code","v":"everysec"},{"t":"text","v":" 等折中；关注 "},{"t":"code","v":"latest_fork_usec"},{"t":"text","v":"。"}]},{"type":"p","inlines":[{"t":"text","v":"监控告警"}]},{"type":"p","inlines":[{"t":"text","v":"连接数、内存、CPU、慢日志条数、延迟分位设阈值，抖的时候有据可查。"}]},{"type":"p","inlines":[{"t":"text","v":"客户端连接池也要配好（如 Lettuce 池大小），避免抖的时候疯狂新建连接雪上加霜。"}]},{"type":"p","inlines":[{"t":"text","v":"一句话收束"}]},{"type":"p","inlines":[{"t":"text","v":"抖动 = 延迟尖刺；先监控和慢日志定位，再治大 Key、重命令、持久化和内存网络。"}]}]},{"id":"redis-Redis抖动是什么，如何解决-抖动和一直慢怎么区分","module":"redis","title":"抖动和一直慢怎么区分","level":"extra","summary":"一直慢：基线延迟整体抬高。抖动：大部分正常，偶发尖刺。排查都看慢日志，但抖动更要抓 …","blocks":[{"type":"p","inlines":[{"t":"text","v":"一直慢：基线延迟整体抬高。抖动：大部分正常，偶发尖刺。排查都看慢日志，但抖动更要抓 尖刺时刻 的 INFO、fork、淘汰、大 Key 操作。"}]}],"parentId":"redis-Redis抖动是什么，如何解决"},{"id":"redis-Redis抖动是什么，如何解决-和性能调优那题重复吗","module":"redis","title":"和性能调优那题重复吗","level":"extra","summary":"不拆两套答案。调优偏「系统性变慢怎么查」；本题偏「什么叫抖、尖刺从哪来」。口述可交叉…","blocks":[{"type":"p","inlines":[{"t":"text","v":"不拆两套答案。调优偏「系统性变慢怎么查」；本题偏「什么叫抖、尖刺从哪来」。口述可交叉引用 "},{"t":"code","v":"07.如何进行Redis性能调优"},{"t":"text","v":"。"}]}],"parentId":"redis-Redis抖动是什么，如何解决"},{"id":"redis-redis为什么这么快","module":"redis","title":"redis为什么这么快","level":"core","summary":"内存：Redis将数据存储在内存中，实现了快速读写操作。","blocks":[{"type":"li","inlines":[{"t":"text","v":"内存"}]},{"type":"li","inlines":[{"t":"text","v":"单线程"}]},{"type":"li","inlines":[{"t":"text","v":"I/O 多路复用"}]},{"type":"li","inlines":[{"t":"text","v":"高效数据结构"}]},{"type":"p","inlines":[{"t":"text","v":"内存：Redis将数据存储在内存中，实现了快速读写操作。"}]},{"type":"p","inlines":[{"t":"text","v":"单线程：采用单线程处理请求，不用加锁，避免了多线程的竞争，也少上下文切换。单线程处理请求说的是「命令执行」单线程，不是整个进程只有一个线程。Redis 6 起网络读写可以多线程，命令仍交给单线程执行。"}]},{"type":"p","inlines":[{"t":"text","v":"I/O 多路复用：一个线程盯很多连接，用 epoll 这类机制，哪个客户端有数据就处理哪个，不用一连接一线程，连接多了也能撑住。"}]},{"type":"p","inlines":[{"t":"text","v":"高效数据结构：SDS、跳表、压缩列表 / listpack、哈希表等按场景选，内存紧、路径短。String、Hash、ZSet 不是随便套一层通用结构。"}]}]},{"id":"redis-redis为什么这么快-Redis-是单线程吗","module":"redis","title":"Redis 是单线程吗","level":"extra","summary":"要拆开说。命令执行是单线程，保证原子性好讲、不用锁。前面接网络、后面刷盘可以有别的线…","blocks":[{"type":"p","inlines":[{"t":"text","v":"要拆开说。命令执行是单线程，保证原子性好讲、不用锁。前面接网络、后面刷盘可以有别的线程：Redis 6+ 的 IO 线程、bio 做关闭文件 / AOF 刷盘等。面试别说成「整个 Redis 只有一个线程」，说「执行命令的主线程是单线程」更准。"}]}],"parentId":"redis-redis为什么这么快"},{"id":"redis-redis为什么这么快-单线程为什么不会成瓶颈","module":"redis","title":"单线程为什么不会成瓶颈","level":"extra","summary":"多数时候瓶颈在内存带宽和网络，不在 CPU。命令本身很轻，单核跑命令往往跑不满。真要…","blocks":[{"type":"p","inlines":[{"t":"text","v":"多数时候瓶颈在内存带宽和网络，不在 CPU。命令本身很轻，单核跑命令往往跑不满。真要压 CPU，多半是个别重命令（KEYS、大 key、复杂聚合），靠规范用法和拆分，不是靠多线程执行命令。"}]}],"parentId":"redis-redis为什么这么快"},{"id":"redis-redis为什么这么快-什么是-IO-多路复用","module":"redis","title":"什么是 I/O 多路复用","level":"extra","summary":"一块说清楚：一个线程同时盯很多个 socket，谁可读可写了就去处理谁，不是一连接一…","blocks":[{"type":"p","inlines":[{"t":"text","v":"一块说清楚：一个线程同时盯很多个 socket，谁可读可写了就去处理谁，不是一连接一线程傻等。"}]},{"type":"p","inlines":[{"t":"text","v":"阻塞 I/O 是 read 卡住整条线程；多路复用先用 select / poll / epoll 问内核「这批 fd 里谁就绪了」，再对就绪的做读写，线程大部分时间不用空等。Linux 上 Redis 常用 epoll：事件驱动，连接多了也稳。"}]},{"type":"p","inlines":[{"t":"text","v":"和 Redis 的关系：主线程靠多路复用收齐客户端请求，再串行执行命令。所以「单线程」扛得住高并发连接——并发在网络侧被复用摊开了，命令侧还是一条线。"}]}],"parentId":"redis-redis为什么这么快"},{"id":"redis-redis为什么这么快-fd-是什么","module":"redis","title":"fd 是什么","level":"extra","summary":"fd 是 file descriptor，文件描述符。在 Linux 里，打开的文件…","blocks":[{"type":"p","inlines":[{"t":"text","v":"fd 是 file descriptor，文件描述符。在 Linux 里，打开的文件、管道、socket 都会分配一个非负整数当编号，程序用这个整数跟内核打交道，不直接拿内核对象指针。"}]},{"type":"p","inlines":[{"t":"text","v":"客户端连上 Redis，内核会给这个连接一个 socket fd。epoll 盯的就是这些 fd：哪个可读了、可写了，再去 read / write。所以笔记里说「一批 fd 谁就绪了」，意思就是「哪些连接有事件了」。"}]}],"parentId":"redis-redis为什么这么快"},{"id":"redis-redis为什么这么快-什么是-epoll-机制","module":"redis","title":"什么是 epoll 机制","level":"extra","summary":"select、poll、epoll 都是 I/O 多路复用的实现，用来一次盯一批 f…","blocks":[{"type":"p","inlines":[{"t":"code","v":"select"},{"t":"text","v":"、"},{"t":"code","v":"poll"},{"t":"text","v":"、"},{"t":"code","v":"epoll"},{"t":"text","v":" 都是 I/O 多路复用的实现，用来一次盯一批 fd，看谁就绪。Linux 上 Redis 默认用 epoll。"}]},{"type":"p","inlines":[{"t":"code","v":"select"},{"t":"text","v":" / "},{"t":"code","v":"poll"},{"t":"text","v":"：每次要把关心的 fd 集合交给内核扫一遍，fd 一多，开销就上去；select 还有 fd 数量上限。能用，连接特别多时不够香。"}]},{"type":"p","inlines":[{"t":"code","v":"epoll"},{"t":"text","v":"：在内核里建一个事件表，fd 就绪了内核主动告诉你（事件驱动），不用每次把整表扫回来。常见两个用法：水平触发（LT）就绪就一直通知，边缘触发（ET）状态变化才通知一次。连接成千上万时，epoll 更稳、更省。"}]},{"type":"p","inlines":[{"t":"text","v":"面试记住：多路复用是思路，epoll 是 Linux 上的高效落地；Redis 靠它一个线程盯海量连接。"}]}],"parentId":"redis-redis为什么这么快"},{"id":"redis-redis为什么这么快-Memcached-和-Redis-有什么区别","module":"redis","title":"Memcached 和 Redis 有什么区别","level":"extra","summary":"面试常按这几条答：","blocks":[{"type":"p","inlines":[{"t":"text","v":"面试常按这几条答："}]},{"type":"p","inlines":[{"t":"text","v":"存储与持久化：Memcached 数据都在内存，进程挂了就没了，也不能超出内存硬扛。Redis 也是内存库，但支持 RDB/AOF 持久化，可以落盘恢复。"}]},{"type":"p","inlines":[{"t":"text","v":"数据类型：Memcached 基本就是简单字符串 kv。Redis 还有 List、Hash、Set、ZSet 等，一个组件能干更多事。"}]},{"type":"p","inlines":[{"t":"text","v":"线程与协议：Memcached 多线程；Redis 命令执行是单线程，和客户端通信的协议也不一样（Redis 用 RESP）。有的旧资料会提 Redis 自己搞过 VM，那套早就废弃了，面试别当重点背。"}]},{"type":"p","inlines":[{"t":"text","v":"单 value 大小：Memcached 单个 value 默认大约 1MB 上限；Redis 单个 string 可以大很多（官方上限 512MB 量级），大对象别随便塞，但能力上宽一截。"}]},{"type":"p","inlines":[{"t":"text","v":"速度：两者都是内存，同量级，别绝对说「Redis 快很多」。Redis 赢在功能面和可持久化；纯缓存、极简 kv，Memcached 也仍有人用。"}]},{"type":"p","inlines":[{"t":"text","v":"高可用：Redis 原生支持主从复制、哨兵、集群等备份与高可用形态；Memcached 本身更弱，要靠客户端或中间层拼。"}]}],"parentId":"redis-redis为什么这么快"},{"id":"redis-说说Redis有哪些数据结构","module":"redis","title":"说说Redis有哪些数据结构","level":"core","summary":"常考五种：String、Hash、List、Set、ZSet。先报齐名字，每种用一句…","blocks":[{"type":"li","inlines":[{"t":"text","v":"String"}]},{"type":"li","inlines":[{"t":"text","v":"Hash"}]},{"type":"li","inlines":[{"t":"text","v":"List"}]},{"type":"li","inlines":[{"t":"text","v":"Set"}]},{"type":"li","inlines":[{"t":"text","v":"ZSet"}]},{"type":"p","inlines":[{"t":"text","v":"常考五种：String、Hash、List、Set、ZSet。先报齐名字，每种用一句话说清楚是什么。"}]},{"type":"p","inlines":[{"t":"text","v":"String：最基本的键值，一个 key 对应一块二进制安全的值，能当字符串、数字、甚至序列化后的对象。"}]},{"type":"p","inlines":[{"t":"text","v":"Hash：一个 key 下多个 field-value，像一张小表 / 一个对象的字段集合。"}]},{"type":"p","inlines":[{"t":"text","v":"List：按插入顺序排的列表，两端都能推入、弹出，语义接近双向链表。"}]},{"type":"p","inlines":[{"t":"text","v":"Set：无序集合，成员唯一，自动去重，支持交并差。"}]},{"type":"p","inlines":[{"t":"text","v":"ZSet（Sorted Set）：带分的集合，成员唯一，按 score 排序，能取排名、取区间。"}]},{"type":"p","inlines":[{"t":"text","v":"另外还有 Bitmap、HyperLogLog、Geo、Stream 等，面试五大门类说全，这几个当补充提一句即可。"}]}]},{"id":"redis-说说Redis有哪些数据结构-redis有哪些应用场景","module":"redis","title":"redis有哪些应用场景","level":"extra","summary":"按场景答，顺带点上用哪种结构：","blocks":[{"type":"p","inlines":[{"t":"text","v":"按场景答，顺带点上用哪种结构："}]},{"type":"p","inlines":[{"t":"text","v":"数据缓存：热点数据放 Redis，扛流量、加速响应，多用 String / Hash。要会穿透、雪崩、一致性。"}]},{"type":"p","inlines":[{"t":"text","v":"会话管理：分布式 Session 共享登录态，多用 String 或 Hash。"}]},{"type":"p","inlines":[{"t":"text","v":"排行榜与计数：热度榜、点赞榜用 ZSet；单纯计数用 String 的 INCR。"}]},{"type":"p","inlines":[{"t":"text","v":"分布式锁：String + "},{"t":"code","v":"SET key token NX EX"},{"t":"text","v":"，复杂再用 Redisson。"}]},{"type":"p","inlines":[{"t":"text","v":"消息队列 / 异步解耦：List 做简单队列，Pub/Sub 做广播，更完整用 Stream 或专业 MQ。"}]},{"type":"p","inlines":[{"t":"text","v":"限流：滑动窗口等，常配合 Lua 保证原子性。"}]},{"type":"p","inlines":[{"t":"text","v":"签到、UV、附近的人：分别常想到 Bitmap、HyperLogLog、Geo。"}]}],"parentId":"redis-说说Redis有哪些数据结构"},{"id":"redis-说说Redis有哪些数据结构-redis不同数据结构的实现原理","module":"redis","title":"redis不同数据结构的实现原理","level":"extra","summary":"对外是五种类型，对内按数据量选编码，小的省内存，大了再换成能扛的结构。","blocks":[{"type":"p","inlines":[{"t":"text","v":"对外是五种类型，对内按数据量选编码，小的省内存，大了再换成能扛的结构。"}]},{"type":"p","inlines":[{"t":"text","v":"String：底层 SDS（简单动态字符串），带长度、可二进制安全，比 C 字符串好用。"}]},{"type":"p","inlines":[{"t":"text","v":"Hash：小用 listpack / 压缩列表，大了转 hashtable（字典）。"}]},{"type":"p","inlines":[{"t":"text","v":"List：现代实现常见 quicklist（快速列表，ziplist/listpack 串起来），兼容量和内存。"}]},{"type":"p","inlines":[{"t":"text","v":"Set：纯整数可能用 intset；否则用 hashtable，只存 key。"}]},{"type":"p","inlines":[{"t":"text","v":"ZSet：小用 listpack；大了是「跳表 + 字典」：跳表按分排序、范围查询，字典按成员 O(1) 找分。"}]},{"type":"p","inlines":[{"t":"text","v":"面试记住一句：类型是 API 视角，编码会随元素个数、大小升级；ZSet 大对象必提跳表。"}]}],"parentId":"redis-说说Redis有哪些数据结构"},{"id":"redis-说说Redis有哪些数据结构-详细说说SDS","module":"redis","title":"详细说说SDS","level":"extra","summary":"SDS 是 Simple Dynamic String，Redis 自己的字符串实现…","blocks":[{"type":"p","inlines":[{"t":"text","v":"SDS 是 Simple Dynamic String，Redis 自己的字符串实现，String 类型底下就是它。"}]},{"type":"p","inlines":[{"t":"text","v":"比 C 字符串强在几处。自带 "},{"t":"code","v":"len"},{"t":"text","v":"，取长度 O(1)，不用每次扫到 "},{"t":"code","v":"\\0"},{"t":"text","v":"。缓冲区可以预留空间，追加时少反复分配。二进制安全：中间可以有 "},{"t":"code","v":"\\0"},{"t":"text","v":"，因为靠长度判断，不靠 "},{"t":"code","v":"\\0"},{"t":"text","v":" 当结尾。拼接时还会检查会不会溢出。"}]},{"type":"p","inlines":[{"t":"text","v":"结构上可以记：头部有长度、分配空间等信息，后面跟字节数组。不同长度用不同头部（sdshdr5/8/16…），小字符串更省。"}]},{"type":"p","inlines":[{"t":"text","v":"面试一句话：SDS = 带长度的动态字节数组，O(1) 长度、可扩容、二进制安全。"}]}],"parentId":"redis-说说Redis有哪些数据结构"},{"id":"redis-说说Redis有哪些数据结构-详细说说跳表","module":"redis","title":"详细说说跳表","level":"extra","summary":"跳表（Skip List）是多层的有序链表。最底层是完整有序链表，上面几层是「快进」…","blocks":[{"type":"p","inlines":[{"t":"text","v":"跳表（Skip List）是多层的有序链表。最底层是完整有序链表，上面几层是「快进」索引，每隔若干节点抽一个升到上一层，查的时候先在高层跳大步，再往下层精细定位，平均查找近似 O(log n)。"}]},{"type":"p","inlines":[{"t":"text","v":"和平衡树比：实现简单，插入删除主要是改指针，不用像红黑树那样频繁旋转；范围查询顺着底层链表扫就行，很适合 ZSet 的按分区间、取 TopN。Redis 大 ZSet 用「跳表 + 字典」：跳表管排序和范围，字典管成员到分数的 O(1) 点查。"}]},{"type":"p","inlines":[{"t":"text","v":"节点会随机出层高，所以是概率平衡，不是严格 AVL 那种。面试提到 ZSet 底层，跳表是必答题。"}]}],"parentId":"redis-说说Redis有哪些数据结构"},{"id":"redis-说说Redis有哪些数据结构-为什么-MySQL-不使用跳表而用-B+-树","module":"redis","title":"为什么 MySQL 不使用跳表而用 B+ 树","level":"extra","summary":"场景不同。Redis ZSet 在内存里，跳表指针多一点无所谓，实现简单、范围扫友好…","blocks":[{"type":"p","inlines":[{"t":"text","v":"场景不同。Redis ZSet 在内存里，跳表指针多一点无所谓，实现简单、范围扫友好。MySQL InnoDB 索引主要在磁盘，一次 I/O 很贵，要尽量「一次读一块、这块里关键字多」。"}]},{"type":"p","inlines":[{"t":"text","v":"B+ 树节点是页（常见 16KB），一个节点能塞很多关键字和子节点指针，树更矮，同样数据量磁盘 I/O 次数更少。叶子串成有序链表，范围查询也友好。跳表层多、节点小、指针多，同等数据下树更高、更碎，对磁盘不划算。"}]},{"type":"p","inlines":[{"t":"text","v":"另外 InnoDB 要聚簇索引、页裂变合并、和 Buffer Pool 配合，B+ 树是成熟方案。内存库可以跳表；磁盘型关系库索引首选 B+ 树。"}]}],"parentId":"redis-说说Redis有哪些数据结构"},{"id":"redis-说说Redis的过期策略","module":"redis","title":"说说Redis的过期策略","level":"core","summary":"Redis采用 定期删除 + 惰性删除的策略","blocks":[{"type":"li","inlines":[{"t":"text","v":"定期删除"}]},{"type":"li","inlines":[{"t":"text","v":"惰性删除"}]},{"type":"p","inlines":[{"t":"text","v":"Redis采用 定期删除 + 惰性删除的策略"}]},{"type":"p","inlines":[{"t":"text","v":"定期删除"}]},{"type":"p","inlines":[{"t":"text","v":"Redis 会定时跑任务，去查带过期时间的 key，过期了就删。大家常说的「大约每 100ms 一轮」，来自默认配置："},{"t":"code","v":"hz"},{"t":"text","v":" 默认是 10，服务器定时任务大约一秒跑 10 次，间隔才约 100ms。不是写死在代码里的 100ms，把 "},{"t":"code","v":"hz"},{"t":"text","v":" 调大，检查会更勤；调小则更稀。"},{"t":"code","v":"hz"},{"t":"text","v":" 太大也会更吃 CPU。"}]},{"type":"p","inlines":[{"t":"text","v":"重点是：它 不会 每一轮把所有带 TTL 的 key 扫一遍。全量扫的话 CPU 容易打满，Redis 会卡。实际是 随机抽一批 来检查，抽到过期的就删。"}]},{"type":"p","inlines":[{"t":"text","v":"所以定期删除的代价是：有些 key 其实已经过期了，但这轮没抽到，还暂时占着内存。"}]},{"type":"p","inlines":[{"t":"text","v":"惰性删除"}]},{"type":"p","inlines":[{"t":"text","v":"弥补定期删「抽不到」的漏洞。当你去 get（或触达）某个 key 时，Redis 先看：它有没有过期时间？是不是已经到期了？到期了就当场删掉，再返回「不存在」。"}]},{"type":"p","inlines":[{"t":"text","v":"等于是：用的时候再检查一次，热 key、常访问的过期键能被清掉。"}]},{"type":"p","inlines":[{"t":"text","v":"两套为什么要一起用"}]},{"type":"p","inlines":[{"t":"text","v":"定期：主动清一批，但不能保证每个过期 key 都被抽中。"}]},{"type":"p","inlines":[{"t":"text","v":"惰性：访问时兜底，但冷 key 从来没人碰，惰性就触发不了。"}]},{"type":"p","inlines":[{"t":"text","v":"所以必须两边一起：定时抽样清一部分，读写时再清一部分。"}]},{"type":"p","inlines":[{"t":"text","v":"这样够不够？还要内存淘汰"}]},{"type":"p","inlines":[{"t":"text","v":"还不够。设想：某个 key 已经过期，定期没抽到，之后也再也没人访问——定期和惰性都碰不到它，它就一直躺在内存里。过期 key 越积越多，内存会一直涨。"}]},{"type":"p","inlines":[{"t":"text","v":"所以过期策略之外，还要配 内存淘汰策略（"},{"t":"code","v":"maxmemory"},{"t":"text","v":" + 各种 LRU/LFU 等）：内存顶满了，按规则踢 key，把这些「过期了但没人管」的也清掉。过期管时间，淘汰管内存顶不住，两件事。"}]}]},{"id":"redis-说说Redis的过期策略-过期的-key-一定会马上删掉吗","module":"redis","title":"过期的 key 一定会马上删掉吗","level":"extra","summary":"不一定。定期是抽样，不是到点全删；惰性是访问才删。没抽到、又没人访问的过期 key，…","blocks":[{"type":"p","inlines":[{"t":"text","v":"不一定。定期是抽样，不是到点全删；惰性是访问才删。没抽到、又没人访问的过期 key，会暂时留着，直到被抽中、被访问，或内存不够触发淘汰。"}]}],"parentId":"redis-说说Redis的过期策略"},{"id":"redis-说说Redis的过期策略-100ms-是固定的吗","module":"redis","title":"100ms 是固定的吗","level":"extra","summary":"不是。默认 hz=10，定时任务大约每秒 10 次，听起来才像「100ms 一次」。…","blocks":[{"type":"p","inlines":[{"t":"text","v":"不是。默认 "},{"t":"code","v":"hz=10"},{"t":"text","v":"，定时任务大约每秒 10 次，听起来才像「100ms 一次」。改 "},{"t":"code","v":"redis.conf"},{"t":"text","v":" 里的 "},{"t":"code","v":"hz"},{"t":"text","v":"（一般 1～500，默认 10）就会变频率。面试可以说：常说的 100ms 是默认观感，本质由 "},{"t":"code","v":"hz"},{"t":"text","v":" 决定，而且每一轮仍是抽样不是全扫。"}]}],"parentId":"redis-说说Redis的过期策略"},{"id":"redis-说说Redis的过期策略-定期删除会不会把-Redis-拖卡","module":"redis","title":"定期删除会不会把 Redis 拖卡","level":"extra","summary":"设计上就是防这个：不扫全量，只随机抽查。hz 等参数会影响定时任务频率，调太猛也会吃…","blocks":[{"type":"p","inlines":[{"t":"text","v":"设计上就是防这个：不扫全量，只随机抽查。"},{"t":"code","v":"hz"},{"t":"text","v":" 等参数会影响定时任务频率，调太猛也会吃 CPU，一般用默认思路「短周期 + 抽样」即可，面试强调「抽样不是全量」就够。"}]}],"parentId":"redis-说说Redis的过期策略"},{"id":"redis-说说Redis的过期策略-过期时间和持久化、主从有什么关系","module":"redis","title":"过期时间和持久化、主从有什么关系","level":"extra","summary":"RDB：生成快照时过期 key 通常不写入；载入时已过期的也会丢掉。AOF：设置过期…","blocks":[{"type":"p","inlines":[{"t":"text","v":"RDB：生成快照时过期 key 通常不写入；载入时已过期的也会丢掉。AOF：设置过期会记命令；真正删掉时也可能记删除；AOF 重写时过期的不会再写进去。主从里，过期删除多由主库执行再同步从库，避免各节点时钟不一致各自乱删。"}]}],"parentId":"redis-说说Redis的过期策略"},{"id":"redis-说说Redis的内存淘汰策略","module":"redis","title":"说说Redis的内存淘汰策略","level":"core","summary":"内存到了 maxmemory 上限，再写入就得按策略腾地方。配置在 redis.co…","blocks":[{"type":"li","inlines":[{"t":"text","v":"maxmemory"}]},{"type":"li","inlines":[{"t":"text","v":"volatile-*（只淘汰带过期的）"}]},{"type":"li","inlines":[{"t":"text","v":"allkeys-*（淘汰全部）"}]},{"type":"li","inlines":[{"t":"text","v":"noeviction"}]},{"type":"p","inlines":[{"t":"text","v":"内存到了 "},{"t":"code","v":"maxmemory"},{"t":"text","v":" 上限，再写入就得按策略腾地方。配置在 "},{"t":"code","v":"redis.conf"},{"t":"text","v":"，例如："}]},{"type":"code","text":"maxmemory-policy volatile-lru"},{"type":"p","inlines":[{"t":"text","v":"这叫 内存淘汰，和过期删除不是一回事：过期是 TTL 到了；淘汰是内存不够了。面试先分清「从哪一堆里挑」和「按什么规则挑」。"}]},{"type":"p","inlines":[{"t":"text","v":"从哪一堆里挑"}]},{"type":"p","inlines":[{"t":"code","v":"volatile-*"},{"t":"text","v":"：只在 设置了过期时间 的 key 里淘汰（expires 那批）。没设 TTL 的 key 不动。"}]},{"type":"p","inlines":[{"t":"code","v":"allkeys-*"},{"t":"text","v":"：在 全部 key 里淘汰（整库 dict），不管有没有过期时间。"}]},{"type":"p","inlines":[{"t":"code","v":"noeviction"},{"t":"text","v":"（有的资料写成 no-eviction）：不淘汰。内存满了，新的写入直接报错。"}]},{"type":"p","inlines":[{"t":"text","v":"注意：如果库里根本没有带过期时间的 key，那 "},{"t":"code","v":"volatile-lru"},{"t":"text","v":" / "},{"t":"code","v":"volatile-random"},{"t":"text","v":" / "},{"t":"code","v":"volatile-ttl"},{"t":"text","v":" 其实淘汰不了谁，表现上就跟 "},{"t":"code","v":"noeviction"},{"t":"text","v":" 差不多——写满照样报错。"}]},{"type":"p","inlines":[{"t":"text","v":"按什么规则挑（常见几种）"}]},{"type":"p","inlines":[{"t":"code","v":"volatile-lru"},{"t":"text","v":"：在带过期的 key 里，优先淘汰 最久没用 的（近似 LRU）。"}]},{"type":"p","inlines":[{"t":"code","v":"volatile-ttl"},{"t":"text","v":"：在带过期的 key 里，优先淘汰 TTL 更短、更快过期 的。"}]},{"type":"p","inlines":[{"t":"code","v":"volatile-random"},{"t":"text","v":"：在带过期的 key 里 随机 淘汰。"}]},{"type":"p","inlines":[{"t":"code","v":"allkeys-lru"},{"t":"text","v":"：在全部 key 里，优先淘汰最久没用的。纯缓存很常见。"}]},{"type":"p","inlines":[{"t":"code","v":"allkeys-random"},{"t":"text","v":"：在全部 key 里随机淘汰。"}]},{"type":"p","inlines":[{"t":"text","v":"（Redis 4+ 还有 "},{"t":"code","v":"volatile-lfu"},{"t":"text","v":" / "},{"t":"code","v":"allkeys-lfu"},{"t":"text","v":"：按访问频率，用得少的先走。面试可以当加分项提一句。）"}]},{"type":"p","inlines":[{"t":"text","v":"怎么选（口述）"}]},{"type":"p","inlines":[{"t":"text","v":"不能丢数据、宁可写入失败："},{"t":"code","v":"noeviction"},{"t":"text","v":"。"}]},{"type":"p","inlines":[{"t":"text","v":"整实例都是可丢的缓存："},{"t":"code","v":"allkeys-lru"},{"t":"text","v":"（或 allkeys-lfu）。"}]},{"type":"p","inlines":[{"t":"text","v":"同一实例里既有要持久的业务 key、又有带 TTL 的缓存：给缓存设过期，用 "},{"t":"code","v":"volatile-lru"},{"t":"text","v":" 等，只踢缓存那批。"}]}]},{"id":"redis-说说Redis的内存淘汰策略-过期策略和淘汰策略有什么区别","module":"redis","title":"过期策略和淘汰策略有什么区别","level":"extra","summary":"过期：key 带 TTL，定期抽样 + 惰性访问时删。淘汰：内存触到 maxmemo…","blocks":[{"type":"p","inlines":[{"t":"text","v":"过期：key 带 TTL，定期抽样 + 惰性访问时删。淘汰：内存触到 "},{"t":"code","v":"maxmemory"},{"t":"text","v":"，按 "},{"t":"code","v":"maxmemory-policy"},{"t":"text","v":" 选 key 删掉腾地方。过期清不干净的冷 key，最后靠淘汰兜底。"}]}],"parentId":"redis-说说Redis的内存淘汰策略"},{"id":"redis-说说Redis的内存淘汰策略-volatile-没设过期会怎样","module":"redis","title":"volatile 没设过期会怎样","level":"extra","summary":"volatile-* 的前提是存在带过期时间的 key。一个都没有时，等价于没法淘汰…","blocks":[{"type":"p","inlines":[{"t":"code","v":"volatile-*"},{"t":"text","v":" 的前提是存在带过期时间的 key。一个都没有时，等价于没法淘汰，写满就和 "},{"t":"code","v":"noeviction"},{"t":"text","v":" 一样报错。所以用 volatile 策略时，缓存 key 一定要设 TTL。"}]}],"parentId":"redis-说说Redis的内存淘汰策略"},{"id":"redis-说说Redis的内存淘汰策略-LRU-和-LFU-怎么选","module":"redis","title":"LRU 和 LFU 怎么选","level":"extra","summary":"看「最近谁没用」用 LRU，好懂，缓存通用。有些 key 短时间爆火之后变冷、更看重…","blocks":[{"type":"p","inlines":[{"t":"text","v":"看「最近谁没用」用 LRU，好懂，缓存通用。有些 key 短时间爆火之后变冷、更看重访问频率，用 LFU。Redis 里都是近似算法，不是严格全量链表，说「近似 LRU/LFU」即可。"}]}],"parentId":"redis-说说Redis的内存淘汰策略"},{"id":"redis-说说Redis的持久化机制","module":"redis","title":"说说Redis的持久化机制","level":"core","summary":"Redis 数据在内存，要落盘靠持久化。常考三种说法：RDB、AOF、以及两者结合的…","blocks":[{"type":"li","inlines":[{"t":"text","v":"RDB"}]},{"type":"li","inlines":[{"t":"text","v":"AOF"}]},{"type":"li","inlines":[{"t":"text","v":"混合持久化"}]},{"type":"p","inlines":[{"t":"text","v":"Redis 数据在内存，要落盘靠持久化。常考三种说法：RDB、AOF、以及两者结合的混合持久化。"}]},{"type":"p","inlines":[{"t":"text","v":"RDB：某个时间点的内存快照，生成二进制的 dump 文件（如 dump.rdb）。靠 "},{"t":"code","v":"SAVE"},{"t":"text","v":" / "},{"t":"code","v":"BGSAVE"},{"t":"text","v":"，一般用 BGSAVE 子进程去做，少堵主线程。优点：文件小、恢复快。缺点：两次快照之间宕机，中间数据会丢。"}]},{"type":"p","inlines":[{"t":"text","v":"AOF：把写命令追加到日志文件。可配同步策略：always（每次写都刷盘，最稳最慢）、everysec（每秒刷，常用折中）、no（交给操作系统）。优点：丢数据更少、可读可重写。缺点：文件往往更大，恢复可能更慢。AOF 会重写（BGREWRITEAOF）压缩体积。"}]},{"type":"p","inlines":[{"t":"text","v":"混合持久化（Redis 4+）：AOF 重写时，先把当时的 RDB 快照写进新 AOF，再追加之后的增量命令。恢复时先载 RDB 再放增量，兼顾恢复速度和数据完整度。现在很多场景默认走这套思路。"}]},{"type":"p","inlines":[{"t":"text","v":"选型：能接受丢几分钟用 RDB 或拉长间隔；要尽量少丢开 AOF everysec；两边都要可开 RDB+AOF，或直接混合。"}]}]},{"id":"redis-说说Redis的持久化机制-RDB-和-AOF-怎么选","module":"redis","title":"RDB 和 AOF 怎么选","level":"extra","summary":"只要灾难恢复快、能接受窗口丢数据，RDB 够用。要接近实时、少丢写，开 AOF，同步…","blocks":[{"type":"p","inlines":[{"t":"text","v":"只要灾难恢复快、能接受窗口丢数据，RDB 够用。要接近实时、少丢写，开 AOF，同步用 everysec。重要业务常 RDB + AOF 或混合：重启快一点，丢得也少一点。"}]}],"parentId":"redis-说说Redis的持久化机制"},{"id":"redis-说说Redis的持久化机制-AOF-的-always、everysec、no-有什么区别","module":"redis","title":"AOF 的 always、everysec、no 有什么区别","level":"extra","summary":"always：每条写命令都 fsync，最安全，性能最差。everysec：每秒 f…","blocks":[{"type":"p","inlines":[{"t":"text","v":"always：每条写命令都 fsync，最安全，性能最差。everysec：每秒 fsync，最多丢约一秒，生产最常见。no：只 write 不主动 fsync，何时落盘看 OS，快但不稳。"}]}],"parentId":"redis-说说Redis的持久化机制"},{"id":"redis-说说Redis的持久化机制-持久化会不会拖慢-Redis","module":"redis","title":"持久化会不会拖慢 Redis","level":"extra","summary":"会有影响。BGSAVE / AOF 重写会 fork 子进程，写时复制可能多占内存；…","blocks":[{"type":"p","inlines":[{"t":"text","v":"会有影响。BGSAVE / AOF 重写会 fork 子进程，写时复制可能多占内存；AOF 刷盘有 I/O。所以要控频率、磁盘要用好的、监控 fork 耗时，别在高峰狂刷重写。"}]}],"parentId":"redis-说说Redis的持久化机制"},{"id":"redis-说说缓存击穿、缓存穿透、缓存雪崩怎么解决","module":"redis","title":"说说缓存击穿、缓存穿透、缓存雪崩怎么解决","level":"core","summary":"三个词容易混，先分清「坏在哪」，再答怎么防。都是缓存没托住，流量打到数据库。","blocks":[{"type":"li","inlines":[{"t":"text","v":"穿透：查不存在的数据"}]},{"type":"li","inlines":[{"t":"text","v":"击穿：热点 key 失效"}]},{"type":"li","inlines":[{"t":"text","v":"雪崩：大批 key 同时失效 / 缓存挂了"}]},{"type":"p","inlines":[{"t":"text","v":"三个词容易混，先分清「坏在哪」，再答怎么防。都是缓存没托住，流量打到数据库。"}]},{"type":"p","inlines":[{"t":"text","v":"缓存穿透"}]},{"type":"p","inlines":[{"t":"text","v":"查的数据 缓存没有、数据库也没有。正常流程：先 Redis，没有再查库，有再回写。数据根本不存在时，每次都 miss，每次都打库。攻击者用海量随机、不重复的假 key，空值缓存也会把 Redis 内存撑爆——所以不能只答「缓存空值」。"}]},{"type":"p","inlines":[{"t":"text","v":"解决要做成纵深防护，面试可按三层答："}]},{"type":"li","inlines":[{"t":"text","v":"参数校验拦截：入口先校验合法性（id > 0、手机号格式等），明显非法的直接挡掉，成本最低。"}]},{"type":"li","inlines":[{"t":"text","v":"布隆过滤器前置：把库里「可能存在」的 id 放进布隆过滤器。请求先问过滤器：一定不存在就拦截；可能存在再放行去 Redis/DB。占内存小、极快；有误判（假阳性），不支持直接删除。"}]},{"type":"li","inlines":[{"t":"text","v":"缓存空值兜底：仍打到库且为空，把空对象写入 Redis，并设 较短过期（比如几分钟）。挡住短时间重复查同一个不存在的 key，又避免恶意随机 key 永久占内存。"}]},{"type":"p","inlines":[{"t":"text","v":"口述总结：校验挡垃圾请求，布隆挡海量假 key，空值 + 短 TTL 做最后兜底。"}]},{"type":"p","inlines":[{"t":"text","v":"缓存击穿"}]},{"type":"p","inlines":[{"t":"text","v":"一个 热点 key 过期（或被删）的瞬间，大量并发一起打到数据库，把库打挂。和穿透的区别：数据本来存在，只是这一刻缓存空了。"}]},{"type":"p","inlines":[{"t":"text","v":"常见解法："}]},{"type":"li","inlines":[{"t":"text","v":"互斥锁 / 单飞：只有一个线程去查库回写，别人等或稍后再读缓存。"}]},{"type":"li","inlines":[{"t":"text","v":"热点永不过期 + 异步刷新：逻辑过期时间放 value 里，到期由后台或拿到锁的线程异步重建，用户仍读旧值。"}]},{"type":"li","inlines":[{"t":"text","v":"提前续期 / 预热：活动前把热点 load 进缓存，临近过期主动续。"}]},{"type":"p","inlines":[{"t":"text","v":"缓存雪崩"}]},{"type":"p","inlines":[{"t":"text","v":"一大片 key 同一时间过期，或 Redis 直接挂了，请求全集群打到数据库。"}]},{"type":"p","inlines":[{"t":"text","v":"常见解法："}]},{"type":"li","inlines":[{"t":"text","v":"过期时间加随机：基础 TTL + 随机抖动，避免同一秒集体失效。"}]},{"type":"li","inlines":[{"t":"text","v":"多级缓存 / 本地缓存：Redis 抖一下还有 Caffeine 等挡一挡。"}]},{"type":"li","inlines":[{"t":"text","v":"Redis 高可用：主从、哨兵、集群，降低整机挂掉概率。"}]},{"type":"li","inlines":[{"t":"text","v":"限流降级熔断：库扛不住时接口限流、返回兜底，保护数据库。"}]},{"type":"li","inlines":[{"t":"text","v":"缓存预热：系统启动或大促前先把热点灌进缓存。"}]}]},{"id":"redis-说说缓存击穿、缓存穿透、缓存雪崩怎么解决-穿透、击穿、雪崩怎么快速区分","module":"redis","title":"穿透、击穿、雪崩怎么快速区分","level":"extra","summary":"穿透：数据根本不存在，恶意或不存在的 key。击穿：单个热点刚好失效。雪崩：很多 k…","blocks":[{"type":"p","inlines":[{"t":"text","v":"穿透：数据根本不存在，恶意或不存在的 key。击穿：单个热点刚好失效。雪崩：很多 key 一起失效，或缓存层整体不可用。"}]}],"parentId":"redis-说说缓存击穿、缓存穿透、缓存雪崩怎么解决"},{"id":"redis-说说缓存击穿、缓存穿透、缓存雪崩怎么解决-为什么说只缓存空值不够","module":"redis","title":"为什么说只缓存空值不够","level":"extra","summary":"攻击 key 不重复、量又大，每个空值都占一条 Redis 记录，内存会被打满。所以…","blocks":[{"type":"p","inlines":[{"t":"text","v":"攻击 key 不重复、量又大，每个空值都占一条 Redis 记录，内存会被打满。所以要前面加校验和布隆过滤器，空值只当短 TTL 兜底。"}]}],"parentId":"redis-说说缓存击穿、缓存穿透、缓存雪崩怎么解决"},{"id":"redis-说说缓存击穿、缓存穿透、缓存雪崩怎么解决-布隆过滤器有什么缺点","module":"redis","title":"布隆过滤器有什么缺点","level":"extra","summary":"有误判：说「存在」时可能其实不存在，请求仍会往后走。说「不存在」则一定不存在，可以放…","blocks":[{"type":"p","inlines":[{"t":"text","v":"有误判：说「存在」时可能其实不存在，请求仍会往后走。说「不存在」则一定不存在，可以放心拦。一般不好直接删元素（要数删除要用 Counting Bloom 等变种）。数据变更时要想好如何重建或增量更新过滤器。"}]}],"parentId":"redis-说说缓存击穿、缓存穿透、缓存雪崩怎么解决"},{"id":"redis-什么是热Key，如何解决","module":"redis","title":"什么是热Key，如何解决","level":"core","summary":"什么是热 Key","blocks":[{"type":"li","inlines":[{"t":"text","v":"单 key QPS 过高"}]},{"type":"li","inlines":[{"t":"text","v":"打满单实例 / 单槽"}]},{"type":"li","inlines":[{"t":"text","v":"本地缓存、拆 key、限流、监控"}]},{"type":"p","inlines":[{"t":"text","v":"什么是热 Key"}]},{"type":"p","inlines":[{"t":"text","v":"某个 key 被访问得特别频繁，流量集中打在 一台 Redis、甚至 Cluster 的一个槽 上。实例 CPU、网卡、连接被打满，别的 key 也被拖慢。秒杀库存、首页配置、爆款商品详情最常见。"}]},{"type":"p","inlines":[{"t":"text","v":"和 缓存击穿 不是一回事：击穿是热点 key 刚好失效，流量打到数据库；热 Key 多半还在 Redis 里，只是 读太猛，Redis 自己先扛不住。"}]},{"type":"p","inlines":[{"t":"text","v":"怎么解决（口述四板斧）"}]},{"type":"p","inlines":[{"t":"text","v":"1. 本地缓存"}]},{"type":"p","inlines":[{"t":"text","v":"应用进程里再垫一层（Caffeine 等）。先读本地，没有再读 Redis。把重复读挡在业务机上，Redis QPS 立刻下来。注意本地有副本，更新要短 TTL 或主动失效，接受短暂不一致。"}]},{"type":"p","inlines":[{"t":"text","v":"2. 请求分摊（拆成多个子 Key）"}]},{"type":"p","inlines":[{"t":"text","v":"把同一个逻辑数据复制到 "},{"t":"code","v":"hot:0:xxx"},{"t":"text","v":" … "},{"t":"code","v":"hot:N:xxx"},{"t":"text","v":"。读的时候按 hash / 随机挑一个子 Key。写的时候要同步改所有副本，或接受短暂不一致后异步刷。目的是把访问打散到多个 key，Cluster 下还能落到不同槽、不同节点。"}]},{"type":"p","inlines":[{"t":"text","v":"3. 限流"}]},{"type":"p","inlines":[{"t":"text","v":"对这个 key 的访问做令牌桶 / 信号量，超了直接失败或走降级，保护 Redis 和下游。治标，常和前两招一起用。"}]},{"type":"p","inlines":[{"t":"text","v":"4. 监控和热点探测"}]},{"type":"p","inlines":[{"t":"code","v":"INFO"},{"t":"text","v":"、监控平台看瞬时 QPS、CPU、网卡。大厂会有热点探测：上报 key 访问次数，判定热 Key 后 SDK 自动本地缓存 把流量拦在应用侧。面试提到「发现热 Key 再动态加本地缓存」会加分。"}]},{"type":"p","inlines":[{"t":"text","v":"怎么选：读多写少、能容忍秒级不一致 → 本地缓存优先；写也多、要打散集群压力 → 拆子 Key；活动峰值再加限流。"}]}]},{"id":"redis-什么是热Key，如何解决-热-Key-和缓存击穿怎么区分","module":"redis","title":"热 Key 和缓存击穿怎么区分","level":"extra","summary":"热 Key：key 还在，读请求把 Redis 打爆。击穿：热点 key 过期或被删…","blocks":[{"type":"p","inlines":[{"t":"text","v":"热 Key：key 还在，读请求把 Redis 打爆。击穿：热点 key 过期或被删，请求打到 DB。一个打 Redis，一个打库。"}]}],"parentId":"redis-什么是热Key，如何解决"},{"id":"redis-什么是热Key，如何解决-拆成多个子-Key-读怎么取","module":"redis","title":"拆成多个子 Key 读怎么取","level":"extra","summary":"读随机或按用户 hash 选一个副本。写要么改所有副本，要么只写主副本再异步同步。一…","blocks":[{"type":"p","inlines":[{"t":"text","v":"读随机或按用户 hash 选一个副本。写要么改所有副本，要么只写主副本再异步同步。一致性要求和击穿那套「单飞回源」要分开讲。"}]}],"parentId":"redis-什么是热Key，如何解决"},{"id":"redis-什么是热Key，如何解决-本地缓存会不会脏很久","module":"redis","title":"本地缓存会不会脏很久","level":"extra","summary":"会。必须设较短过期，或订阅失效消息 / 发版清缓存。强一致别只靠本地缓存。","blocks":[{"type":"p","inlines":[{"t":"text","v":"会。必须设较短过期，或订阅失效消息 / 发版清缓存。强一致别只靠本地缓存。"}]}],"parentId":"redis-什么是热Key，如何解决"},{"id":"redis-什么是大Key，如何解决","module":"redis","title":"什么是大Key，如何解决","level":"core","summary":"什么是大 Key","blocks":[{"type":"li","inlines":[{"t":"text","v":"单个 key 体积或元素过多"}]},{"type":"li","inlines":[{"t":"text","v":"网络慢、堵主线程、占内存"}]},{"type":"li","inlines":[{"t":"text","v":"先排查再拆分 / 压缩 / 异步删 / SCAN"}]},{"type":"p","inlines":[{"t":"text","v":"什么是大 Key"}]},{"type":"p","inlines":[{"t":"text","v":"某个 key 对应的 数据太大：String 的 value 很长，或 List/Hash/Set/ZSet 元素特别多。业界常把单 key 到 10KB 以上 当预警线，没有官方死数字，看实例规格和命令耗时。"}]},{"type":"p","inlines":[{"t":"text","v":"危害三句话："}]},{"type":"li","inlines":[{"t":"text","v":"网络：一次 GET 回一大包，RTT 被撑大"}]},{"type":"li","inlines":[{"t":"text","v":"单线程：分配、序列化、删除都在主线程，一条命令卡住后面全等"}]},{"type":"li","inlines":[{"t":"text","v":"内存：一个 key 占一大块，挤掉别的缓存，严重时内存顶满、OOM"}]},{"type":"p","inlines":[{"t":"text","v":"和 热 Key 不同：热 Key 是访问次数多；大 Key 是体积大。一个 key 可以又热又大，更要命。"}]},{"type":"p","inlines":[{"t":"text","v":"怎么排查"}]},{"type":"p","inlines":[{"t":"text","v":"性能掉下来、慢日志里却是普通 "},{"t":"code","v":"GET"},{"t":"text","v":"/"},{"t":"code","v":"DEL"},{"t":"text","v":"，优先怀疑大 Key。"}]},{"type":"p","inlines":[{"t":"text","v":"1. "},{"t":"code","v":"redis-cli --bigkeys"}]},{"type":"p","inlines":[{"t":"text","v":"按类型统计最大的 String 长度、集合元素个数。底层是 SCAN，不是一次 "},{"t":"code","v":"KEYS"},{"t":"text","v":" 扫死，但仍占 CPU。线上加间隔、尽量打 从库："}]},{"type":"code","text":"redis-cli --bigkeys -i 0.1"},{"type":"p","inlines":[{"t":"text","v":"输出里看 Biggest string / list / hash，以及各类型平均大小。集合类扫的是 元素个数，个数多不等于一定最吃内存，还要结合业务估每个元素多大。"}]},{"type":"p","inlines":[{"t":"text","v":"2. 对单个 key 看细节"}]},{"type":"li","inlines":[{"t":"code","v":"DEBUG OBJECT key"},{"t":"text","v":"：编码、"},{"t":"code","v":"serializedLength"},{"t":"text","v":"、LRU 等，是调试命令，长度是估算"}]},{"type":"li","inlines":[{"t":"text","v":"Redis 4.0+ 用 "},{"t":"code","v":"MEMORY USAGE key"},{"t":"text","v":"：估这个 key 占多少字节。Hash 等会 抽样，加 "},{"t":"code","v":"SAMPLES"},{"t":"text","v":" 更准也更吃 CPU"}]},{"type":"p","inlines":[{"t":"text","v":"怎么解决（口述）"}]},{"type":"p","inlines":[{"t":"text","v":"1. 拆分"}]},{"type":"p","inlines":[{"t":"text","v":"大 List 拆成 list1、list2；大 Hash 按用户/区间拆成多个 key（一百万用户拆 200 个 Hash，每个五千条）。读写带上分片规则。"}]},{"type":"p","inlines":[{"t":"text","v":"2. 压缩"}]},{"type":"p","inlines":[{"t":"text","v":"业务侧 gzip 后再 SET，换 CPU 换内存和带宽。要能接受解压开销。"}]},{"type":"p","inlines":[{"t":"text","v":"3. 删除别堵主线程"}]},{"type":"p","inlines":[{"t":"text","v":"删大 Key 用 "},{"t":"code","v":"UNLINK"},{"t":"text","v":"（4.0+），或开 lazy-free（过期/淘汰/用户 DEL 都可配），释放丢给后台。"}]},{"type":"p","inlines":[{"t":"text","v":"4. 遍历用 SCAN"}]},{"type":"p","inlines":[{"t":"text","v":"别对大集合 "},{"t":"code","v":"KEYS"},{"t":"text","v":" / 一次 "},{"t":"code","v":"SMEMBERS"},{"t":"text","v":" 全拉。"},{"t":"code","v":"SCAN"},{"t":"text","v":"/"},{"t":"code","v":"HSCAN"},{"t":"text","v":"/"},{"t":"code","v":"SSCAN"},{"t":"text","v":"/"},{"t":"code","v":"ZSCAN"},{"t":"text","v":" 分批。"}]},{"type":"p","inlines":[{"t":"text","v":"根上还是架构：别往一个 key 里塞全量；监控内存和慢日志，发现了再拆。"}]}]},{"id":"redis-什么是大Key，如何解决-大-Key-和热-Key-怎么区分","module":"redis","title":"大 Key 和热 Key 怎么区分","level":"extra","summary":"大：体积或元素多。热：QPS 高。排查命令不同：--bigkeys / MEMORY…","blocks":[{"type":"p","inlines":[{"t":"text","v":"大：体积或元素多。热：QPS 高。排查命令不同："},{"t":"code","v":"--bigkeys"},{"t":"text","v":" / "},{"t":"code","v":"MEMORY USAGE"},{"t":"text","v":" vs 监控 QPS、热点探测。解法也不同：拆体积 vs 本地缓存/拆副本。"}]}],"parentId":"redis-什么是大Key，如何解决"},{"id":"redis-什么是大Key，如何解决---bigkeys-会不会把-Redis-打挂","module":"redis","title":"--bigkeys 会不会把 Redis 打挂","level":"extra","summary":"会有压力，因为要 SCAN。高峰别对主库狂扫，加 -i，优先从库。它统计的集合是「元…","blocks":[{"type":"p","inlines":[{"t":"text","v":"会有压力，因为要 SCAN。高峰别对主库狂扫，加 "},{"t":"code","v":"-i"},{"t":"text","v":"，优先从库。它统计的集合是「元素最多」，不是「内存最大」。"}]}],"parentId":"redis-什么是大Key，如何解决"},{"id":"redis-什么是大Key，如何解决-DEBUG-OBJECT-和-MEMORY-USAGE-怎么选","module":"redis","title":"DEBUG OBJECT 和 MEMORY USAGE 怎么选","level":"extra","summary":"4.0 以前只能看 DEBUG OBJECT 的序列化长度，误差大。4.0 之后估内…","blocks":[{"type":"p","inlines":[{"t":"text","v":"4.0 以前只能看 "},{"t":"code","v":"DEBUG OBJECT"},{"t":"text","v":" 的序列化长度，误差大。4.0 之后估内存用 "},{"t":"code","v":"MEMORY USAGE"},{"t":"text","v":"；"},{"t":"code","v":"SAMPLES"},{"t":"text","v":" 越大越准、越慢。"}]}],"parentId":"redis-什么是大Key，如何解决"},{"id":"redis-如何解决缓存和数据库双写不一致","module":"redis","title":"如何解决缓存和数据库双写不一致","level":"core","summary":"这题和「如何保证缓存和数据库的最终一致性」是 同一类题。截图问的是 现象（双写把缓存…","blocks":[{"type":"li","inlines":[{"t":"text","v":"双写时序会脏缓存"}]},{"type":"li","inlines":[{"t":"text","v":"Cache Aside：先库后删缓存"}]},{"type":"li","inlines":[{"t":"text","v":"锁 / Canal / TTL 兜底"}]},{"type":"li","inlines":[{"t":"text","v":"缓存场景多是最终一致"}]},{"type":"p","inlines":[{"t":"text","v":"这题和「如何保证缓存和数据库的最终一致性」是 同一类题。截图问的是 现象（双写把缓存写脏了怎么办）；「最终一致」问的是 目标（不强求时刻一样，多久对齐、靠什么对齐）。合成时用现在这个标题当主问题，口述时主动说：我们做的是最终一致，不是跨机事务那种强一致。"}]},{"type":"p","inlines":[{"t":"text","v":"不一致怎么发生"}]},{"type":"p","inlines":[{"t":"text","v":"更新时既写库又写缓存，两步不是原子的，并发一插就脏。"}]},{"type":"p","inlines":[{"t":"text","v":"典型乱序：线程 3 缓存未命中，读到库里旧值 10；线程 2 把库改成 6 并更新了缓存；线程 3 再把缓存写成 10。库已经是 6，缓存却是旧的 10。"}]},{"type":"p","inlines":[{"t":"text","v":"所以 先改库再改缓存 也会翻车，读回源和写缓存交叉才是坑。"}]},{"type":"p","inlines":[{"t":"text","v":"常用解法（口述）"}]},{"type":"p","inlines":[{"t":"text","v":"1. Cache Aside（旁路缓存）——默认先背这个"}]},{"type":"li","inlines":[{"t":"text","v":"读：先 Redis，没有再查库，回写缓存"}]},{"type":"li","inlines":[{"t":"text","v":"写：先更新数据库，再删除缓存，不要「更新缓存」"}]},{"type":"p","inlines":[{"t":"text","v":"下次读 miss 再从库加载。短暂 miss 可以接受，避免用旧值去 覆盖 新缓存。删失败可重试或丢队列补删。"}]},{"type":"p","inlines":[{"t":"text","v":"并发仍可能：删完缓存前，另一个请求把旧值又写回缓存。补丁是 延迟双删：改库后删一次，过几十到几百毫秒再删一次，把「慢读回源」写回去的脏数据清掉。仍是最终一致。"}]},{"type":"p","inlines":[{"t":"text","v":"2. 更新时加锁"}]},{"type":"p","inlines":[{"t":"text","v":"同一资源的写（以及回源写缓存）串行，脏覆盖概率下降，吞吐也下降。热点写入才上。"}]},{"type":"p","inlines":[{"t":"text","v":"3. 听 binlog 异步刷新（Canal 等）"}]},{"type":"p","inlines":[{"t":"text","v":"业务只写库。Canal 订阅 binlog，再删或更新 Redis。缓存以库的提交为准，业务代码少踩双写时序。延迟一般是秒级内，仍是最终一致；Canal 堆积时要监控。"}]},{"type":"p","inlines":[{"t":"text","v":"4. TTL 兜底"}]},{"type":"p","inlines":[{"t":"text","v":"所有方案都给缓存过期时间。最坏脏数据也只会活到 TTL。读多写少时这是最后一道保险。"}]},{"type":"p","inlines":[{"t":"text","v":"怎么选"}]},{"type":"p","inlines":[{"t":"text","v":"一般业务：Cache Aside + 删缓存 + TTL，必要时延迟双删。"}]},{"type":"p","inlines":[{"t":"text","v":"写多、要少踩时序：binlog 订阅。"}]},{"type":"p","inlines":[{"t":"text","v":"极热点写：再加锁。"}]},{"type":"p","inlines":[{"t":"text","v":"库存扣减等强一致：别只靠缓存，库用条件更新 / 唯一约束，缓存当加速。"}]}]},{"id":"redis-如何解决缓存和数据库双写不一致-「最终一致」和截图那题有什么区别","module":"redis","title":"「最终一致」和截图那题有什么区别","level":"extra","summary":"没必要拆成两道。截图 = 并发双写把缓存写脏（问题）；最终一致 = 允许短暂不一致、…","blocks":[{"type":"p","inlines":[{"t":"text","v":"没必要拆成两道。截图 = 并发双写把缓存写脏（问题）；最终一致 = 允许短暂不一致、保证过一阵对齐（目标）。答案都是删缓存、延迟双删、binlog、TTL。面试官换问法，一套稿子。"}]}],"parentId":"redis-如何解决缓存和数据库双写不一致"},{"id":"redis-如何解决缓存和数据库双写不一致-为什么写的时候删缓存，不更新缓存","module":"redis","title":"为什么写的时候删缓存，不更新缓存","level":"extra","summary":"更新缓存要用「刚写入库的新值」。并发读可能拿着更旧的库快照再 SET，把新值盖掉。删…","blocks":[{"type":"p","inlines":[{"t":"text","v":"更新缓存要用「刚写入库的新值」。并发读可能拿着更旧的库快照再 SET，把新值盖掉。删掉让下次读以库为准，更安全。"}]}],"parentId":"redis-如何解决缓存和数据库双写不一致"},{"id":"redis-如何解决缓存和数据库双写不一致-延迟双删间隔怎么定","module":"redis","title":"延迟双删间隔怎么定","level":"extra","summary":"大于「一次读库+写缓存」的耗时，常见 200ms～1s 量级，按 p99 调。第二次…","blocks":[{"type":"p","inlines":[{"t":"text","v":"大于「一次读库+写缓存」的耗时，常见 200ms～1s 量级，按 p99 调。第二次删失败要有重试，否则脏数据会活到 TTL。"}]}],"parentId":"redis-如何解决缓存和数据库双写不一致"},{"id":"redis-怎么实现Redis高可用","module":"redis","title":"怎么实现Redis高可用","level":"core","summary":"高可用要解决的是：单点挂了还能继续服务。面试常背三层，由浅到深：主从 → 哨兵 → …","blocks":[{"type":"li","inlines":[{"t":"text","v":"主从复制：读写分离、从可升主"}]},{"type":"li","inlines":[{"t":"text","v":"哨兵：监控 + 自动故障转移"}]},{"type":"li","inlines":[{"t":"text","v":"集群：16384 槽分片 + 主从"}]},{"type":"p","inlines":[{"t":"text","v":"高可用要解决的是：单点挂了还能继续服务。面试常背三层，由浅到深：主从 → 哨兵 → 集群。主从只解决「有副本」；哨兵解决「主挂了谁自动顶上」；集群再叠加「数据分片扩容」。"}]},{"type":"p","inlines":[{"t":"text","v":"1. 主从复制"}]},{"type":"p","inlines":[{"t":"text","v":"一台主、多台从。主处理写，把变更同步给从；从可扛读，减轻主压力。"}]},{"type":"p","inlines":[{"t":"text","v":"主挂了，可以把某个从升成新主，继续对外服务。但 纯主从不会自己选主：要人改配置、或靠脚本/运维介入，切换慢、容易手滑。"}]},{"type":"p","inlines":[{"t":"text","v":"所以主从是底座（有副本），还不够「自动」高可用。"}]},{"type":"p","inlines":[{"t":"text","v":"2. 哨兵机制（Sentinel）"}]},{"type":"p","inlines":[{"t":"text","v":"哨兵是一组独立进程，盯着主从是否存活。主挂了，哨兵们协商后 自动把一个从升成新主，并通知客户端改连新主。"}]},{"type":"p","inlines":[{"t":"text","v":"生产一般部署 多个哨兵（奇数个常见，如 3），互相监督，避免一个哨兵误判。主从 + 哨兵 = 单机数据量场景下最常见的高可用组合：不换架构，先把故障转移自动化。"}]},{"type":"p","inlines":[{"t":"text","v":"细节见下文拓展「什么是 Redis 哨兵机制」。"}]},{"type":"p","inlines":[{"t":"text","v":"3. 集群模式（Redis Cluster）"}]},{"type":"p","inlines":[{"t":"text","v":"数据按 16384 个哈希槽 分片到多组主节点上，每组主再挂从。某个主挂了，它的从可以顶上；整体还能横向扩容容量和吞吐。"}]},{"type":"p","inlines":[{"t":"text","v":"适合数据量大、单机内存不够、要分片扩容的场景。原理、丢写风险、整集群不可用条件，见下面拓展。"}]},{"type":"p","inlines":[{"t":"text","v":"怎么选（口述）"}]},{"type":"li","inlines":[{"t":"text","v":"数据量不大、要读写分离 + 自动切主：主从 + 哨兵"}]},{"type":"li","inlines":[{"t":"text","v":"数据量/QPS 顶不住单机、要分片：Cluster"}]},{"type":"li","inlines":[{"t":"text","v":"只开主从不配哨兵：有副本，但故障转移靠人，别说成完整高可用"}]}]},{"id":"redis-怎么实现Redis高可用-什么是-Redis-哨兵机制","module":"redis","title":"什么是 Redis 哨兵机制","level":"extra","summary":"哨兵 = Redis 官方的 高可用组件：监控主从，发现主挂了就 自动故障转移。","blocks":[{"type":"p","inlines":[{"t":"text","v":"哨兵 = Redis 官方的 高可用组件：监控主从，发现主挂了就 自动故障转移。"}]},{"type":"p","inlines":[{"t":"text","v":"要背的流程："}]},{"type":"li","inlines":[{"t":"text","v":"监控：多个哨兵定期 ping 主从"}]},{"type":"li","inlines":[{"t":"text","v":"主观下线（SDOWN）：某个哨兵自己觉得主长时间无响应"}]},{"type":"li","inlines":[{"t":"text","v":"客观下线（ODOWN）：达到配置的 quorum（够多个哨兵同意）才认定主真挂了，避免单哨兵误判"}]},{"type":"li","inlines":[{"t":"text","v":"故障转移：选出一个合适的从升主，其余从改认新主；客户端通过哨兵拿到最新主地址"}]},{"type":"p","inlines":[{"t":"text","v":"截图里把 monitor / judge / failover 拆成多种「哨兵进程」，口述时别照背成「四种进程」。实际是 多个 Sentinel 实例 各自完成监控、投票、选主；逻辑上可以理解成「监控 → 判定下线 → 执行切换」三步。"}]},{"type":"p","inlines":[{"t":"text","v":"要点：哨兵自己也要多实例；只部署一个哨兵，哨兵挂了高可用就断了。"}]}],"parentId":"redis-怎么实现Redis高可用"},{"id":"redis-怎么实现Redis高可用-Redis-集群的原理是什么","module":"redis","title":"Redis 集群的原理是什么","level":"extra","summary":"Cluster 用 分片 + 主从 做扩容和高可用。","blocks":[{"type":"p","inlines":[{"t":"text","v":"Cluster 用 分片 + 主从 做扩容和高可用。"}]},{"type":"p","inlines":[{"t":"text","v":"分片"}]},{"type":"p","inlines":[{"t":"text","v":"全库固定 16384 个槽。key 一般算 "},{"t":"code","v":"CRC16(key) % 16384"},{"t":"text","v":" 落到某个槽；每个主负责一段槽。客户端连任意节点，槽不对会返回 "},{"t":"code","v":"MOVED"},{"t":"text","v":"/"},{"t":"code","v":"ASK"},{"t":"text","v":"，再打到正确节点。"}]},{"type":"p","inlines":[{"t":"text","v":"主从"}]},{"type":"p","inlines":[{"t":"text","v":"每个主可带若干从，复制主上的槽数据。主挂了，集群内协商把对应从升主，该段槽继续可写。"}]},{"type":"p","inlines":[{"t":"text","v":"和哨兵的差别"}]},{"type":"p","inlines":[{"t":"text","v":"哨兵不负责分片，只管「这一套主从谁当主」；Cluster 自带分片和节点间 Gossip，节点对等，没有单独的「集群管理中心」。"}]}],"parentId":"redis-怎么实现Redis高可用"},{"id":"redis-怎么实现Redis高可用-Redis-集群会有写操作丢失吗？为什么","module":"redis","title":"Redis 集群会有写操作丢失吗？为什么","level":"extra","summary":"会。 主从复制默认是 异步 的。","blocks":[{"type":"p","inlines":[{"t":"text","v":"会。 主从复制默认是 异步 的。"}]},{"type":"p","inlines":[{"t":"text","v":"客户端写主：主执行完就回 OK，不等 从确认复制完成。若主刚回成功就挂，从还没收到这条写，从升主后这条写就没了。"}]},{"type":"p","inlines":[{"t":"text","v":"怎么降风险（降不完）："}]},{"type":"li","inlines":[{"t":"text","v":"监控复制延迟、主从健康"}]},{"type":"li","inlines":[{"t":"text","v":"合理持久化（AOF 等），方便崩溃恢复"}]},{"type":"li","inlines":[{"t":"text","v":"业务侧关键确认 / 幂等；对关键写可用 "},{"t":"code","v":"WAIT"},{"t":"text","v":" 等主等从确认，但延迟升高，且仍非跨机事务强一致"}]},{"type":"p","inlines":[{"t":"text","v":"口述收束：异步复制换性能，丢写风险抹不掉，只能压低概率。"}]}],"parentId":"redis-怎么实现Redis高可用"},{"id":"redis-怎么实现Redis高可用-Redis-集群什么情况下会导致整个集群不可用","module":"redis","title":"Redis 集群什么情况下会导致整个集群不可用","level":"extra","summary":"常见坑：","blocks":[{"type":"p","inlines":[{"t":"text","v":"常见坑："}]},{"type":"li","inlines":[{"t":"text","v":"多个主同时挂且对应从升不起来"}]},{"type":"p","inlines":[{"t":"text","v":"某段槽既没主也没可用从，整段槽不可用；若挂到多数主、大量槽失效，业务会感觉「集群挂了」。"}]},{"type":"li","inlines":[{"t":"text","v":"网络分区 / 脑裂倾向"}]},{"type":"p","inlines":[{"t":"text","v":"节点互相失联，选主、槽迁移乱套，读写失败或数据冲突。"}]},{"type":"li","inlines":[{"t":"text","v":"配置严重不一致"}]},{"type":"p","inlines":[{"t":"text","v":"节点加入失败、槽分配错乱，集群进不了稳定态。"}]},{"type":"li","inlines":[{"t":"text","v":"内存打满 / 节点集体崩溃"}]},{"type":"p","inlines":[{"t":"text","v":"淘汰失败、OOM、机器扛不住，服务整体劣化甚至不可用。"}]},{"type":"p","inlines":[{"t":"text","v":"怎么防：每个主至少带从并演练切主；哨兵/Cluster 节点别单点；配置统一并监控；网络尽量稳定；内存与容量提前扩。"}]},{"type":"p","inlines":[{"t":"text","v":"注意：Redis Cluster 没有 单独的「管理节点」角色；别把「管理节点全挂」当成标准答案。等价说法是：多数主故障、或分区导致无法形成可用拓扑，集群就会大面积不可用。"}]}],"parentId":"redis-怎么实现Redis高可用"},{"id":"redis-Redis支持事务吗","module":"redis","title":"Redis支持事务吗","level":"core","summary":"支持。 用 MULTI / EXEC / DISCARD / WATCH 把一组命令…","blocks":[{"type":"li","inlines":[{"t":"text","v":"支持，但不是 MySQL 那种事务"}]},{"type":"li","inlines":[{"t":"text","v":"MULTI 入队 → EXEC 串行执行"}]},{"type":"li","inlines":[{"t":"text","v":"不支持回滚；WATCH 做乐观锁"}]},{"type":"p","inlines":[{"t":"text","v":"支持。 用 "},{"t":"code","v":"MULTI"},{"t":"text","v":" / "},{"t":"code","v":"EXEC"},{"t":"text","v":" / "},{"t":"code","v":"DISCARD"},{"t":"text","v":" / "},{"t":"code","v":"WATCH"},{"t":"text","v":" 把一组命令打包执行。但和关系库事务不一样：保证的是 排队后一口气串行跑完、中间不被别的客户端插队，不做失败回滚。"}]},{"type":"p","inlines":[{"t":"text","v":"事务是什么（口述）"}]},{"type":"p","inlines":[{"t":"text","v":"一次事务 = 一组命令。"},{"t":"code","v":"MULTI"},{"t":"text","v":" 之后命令先入队（回 "},{"t":"code","v":"QUEUED"},{"t":"text","v":"），"},{"t":"code","v":"EXEC"},{"t":"text","v":" 才真正执行。执行期间主线程串行跑完这一批，别的客户端命令插不进来。"}]},{"type":"p","inlines":[{"t":"text","v":"三阶段："}]},{"type":"li","inlines":[{"t":"text","v":"开启："},{"t":"code","v":"MULTI"}]},{"type":"li","inlines":[{"t":"text","v":"入队：命令进队列，不立刻改数据"}]},{"type":"li","inlines":[{"t":"text","v":"执行："},{"t":"code","v":"EXEC"},{"t":"text","v":" 触发；"},{"t":"code","v":"DISCARD"},{"t":"text","v":" 则清空队列、放弃事务"}]},{"type":"p","inlines":[{"t":"text","v":"和 MySQL 事务差在哪"}]},{"type":"li","inlines":[{"t":"text","v":"没有回滚：某条执行期报错，不会把已成功的命令撤销，后面该跑还跑"}]},{"type":"li","inlines":[{"t":"text","v":"隔离感来自单线程串行，不是多版本 / 锁那一套完整 ACID"}]},{"type":"li","inlines":[{"t":"text","v":"要「读到的值没被别人改再写」，靠 "},{"t":"code","v":"WATCH"},{"t":"text","v":" 乐观锁，不是靠行锁"}]},{"type":"p","inlines":[{"t":"text","v":"所以面试别说「不支持事务」，说「支持轻量事务，语义和数据库事务不同」。"}]},{"type":"p","inlines":[{"t":"text","v":"错误怎么处理（必背）"}]},{"type":"p","inlines":[{"t":"text","v":"入队时语法/命令错误（参数个数错、命令不存在等）"}]},{"type":"p","inlines":[{"t":"code","v":"EXEC"},{"t":"text","v":" 会整单作废："},{"t":"code","v":"EXECABORT Transaction discarded because of previous errors."},{"t":"text","v":"，队列里命令 一条都不执行。截图里写「全部回滚」，更准确说是 根本没执行，谈不上回滚已提交的结果。"}]},{"type":"p","inlines":[{"t":"text","v":"执行期逻辑错误（如对字符串 "},{"t":"code","v":"INCR"},{"t":"text","v":"）"}]},{"type":"p","inlines":[{"t":"text","v":"该条返回 error，后面正确的命令照样执行。没有自动回滚。"}]},{"type":"p","inlines":[{"t":"text","v":"设计取舍：简单、快，不维护复杂回滚状态。"}]}]},{"id":"redis-Redis支持事务吗-MULTI--EXEC--DISCARD--WATCH-各干什么","module":"redis","title":"MULTI / EXEC / DISCARD / WATCH 各干什么","level":"extra","summary":"MULTI：开事务，之后命令入队，固定回 OK","blocks":[{"type":"li","inlines":[{"t":"code","v":"MULTI"},{"t":"text","v":"：开事务，之后命令入队，固定回 "},{"t":"code","v":"OK"}]},{"type":"li","inlines":[{"t":"code","v":"EXEC"},{"t":"text","v":"：按入队顺序执行，返回各命令结果数组；被 "},{"t":"code","v":"WATCH"},{"t":"text","v":" 打断时返回 "},{"t":"code","v":"nil"}]},{"type":"li","inlines":[{"t":"code","v":"DISCARD"},{"t":"text","v":"：主动放弃，清队列，退出事务状态"}]},{"type":"li","inlines":[{"t":"code","v":"WATCH key..."},{"t":"text","v":"：监控 key；"},{"t":"code","v":"EXEC"},{"t":"text","v":" 前若被别的客户端改过（或删），整笔事务不执行"}]}],"parentId":"redis-Redis支持事务吗"},{"id":"redis-Redis支持事务吗-WATCH-怎么当乐观锁用","module":"redis","title":"WATCH 怎么当乐观锁用","level":"extra","summary":"典型：改余额。","blocks":[{"type":"p","inlines":[{"t":"text","v":"典型：改余额。"}]},{"type":"code","text":"WATCH balance\nMULTI\nDECRBY balance 20\nINCRBY debt 20\nEXEC"},{"type":"p","inlines":[{"t":"code","v":"WATCH"},{"t":"text","v":" 到 "},{"t":"code","v":"EXEC"},{"t":"text","v":" 之间若有人改了 "},{"t":"code","v":"balance"},{"t":"text","v":"，"},{"t":"code","v":"EXEC"},{"t":"text","v":" 返回 "},{"t":"code","v":"nil"},{"t":"text","v":"，队列作废。像乐观锁：版本变了就重试——重新 "},{"t":"code","v":"GET"},{"t":"text","v":" 最新值，再 "},{"t":"code","v":"WATCH"},{"t":"text","v":" + "},{"t":"code","v":"MULTI"},{"t":"text","v":"。"}]},{"type":"p","inlines":[{"t":"code","v":"WATCH"},{"t":"text","v":" 监控持续到 "},{"t":"code","v":"EXEC"},{"t":"text","v":"（成功或因冲突失败都会结束本次监视）；也可用 "},{"t":"code","v":"UNWATCH"},{"t":"text","v":" 主动取消。"}]}],"parentId":"redis-Redis支持事务吗"},{"id":"redis-Redis支持事务吗-Redis-事务算不算原子性","module":"redis","title":"Redis 事务算不算原子性","level":"extra","summary":"要拆开说：","blocks":[{"type":"p","inlines":[{"t":"text","v":"要拆开说："}]},{"type":"li","inlines":[{"t":"text","v":"打包执行原子："},{"t":"code","v":"EXEC"},{"t":"text","v":" 时这一批连续跑完，不被插队 —— 有"}]},{"type":"li","inlines":[{"t":"text","v":"要么全成功要么全失败：没有；执行期单条失败不回滚整笔"}]},{"type":"li","inlines":[{"t":"text","v":"入队语法错误：整笔不执行 —— 像「全不跑」，仍不是执行后退回"}]},{"type":"p","inlines":[{"t":"text","v":"需要真正「一组命令逻辑要么全成」时，更常用 Lua 脚本（服务端一次执行完），面试可顺带提一句。"}]}],"parentId":"redis-Redis支持事务吗"},{"id":"redis-Redis支持事务吗-Lua-脚本比-MULTIEXEC-强在哪","module":"redis","title":"Lua 脚本比 MULTI/EXEC 强在哪","level":"extra","summary":"Redis 2.6 起支持 Lua。常考三个优点：","blocks":[{"type":"p","inlines":[{"t":"text","v":"Redis 2.6 起支持 Lua。常考三个优点："}]},{"type":"li","inlines":[{"t":"text","v":"少网络往返：本来 5 条命令 5 次 RTT，脚本一次送上去在服务端跑完。"}]},{"type":"li","inlines":[{"t":"text","v":"真正按脚本原子执行：脚本执行期间别的客户端命令插不进来，适合「判断 + 修改 + 设过期」这类临界区（分布式锁就靠它）。"}]},{"type":"li","inlines":[{"t":"text","v":"能替代一部分事务用法：要复杂条件逻辑时，Lua 比 "},{"t":"code","v":"MULTI"},{"t":"text","v":" 入队更灵活；且脚本内逻辑一次跑完，不像事务那样「执行期某条失败还不回滚」。"}]},{"type":"p","inlines":[{"t":"text","v":"注意：Lua 跑太久会堵 Redis 主线程，脚本要短、别在里面干重活。"}]}],"parentId":"redis-Redis支持事务吗"}]
